// ============================================================================
// 途中再生 .save: メディア隣ではなく %LOCALAPPDATA%\oggYSED\resume\ へ。
// 管理者権限不要・再起動後も残りやすい(TEMPより耐性)。パス衝突回避にフルパスハッシュを使う。
// 旧仕様(メディア隣の *.save)は読込時のみフォールバックし、書込成功時に掃除。
// ============================================================================
static ULONGLONG ResumeSaveHashPath(LPCTSTR path)
{
	ULONGLONG h = 14695981039346656037ULL;
	if (!path) return h;
	for (const TCHAR* p = path; *p; ++p) {
		TCHAR c = *p;
		if (c >= _T('A') && c <= _T('Z')) c = (TCHAR)(c - _T('A') + _T('a'));
		if (c == _T('/')) c = _T('\\');
		h ^= (ULONGLONG)(unsigned)(TCHAR)c;
		h *= 1099511628211ULL;
	}
	return h;
}

static CString ResumeSaveDir()
{
	TCHAR base[MAX_PATH] = {};
	DWORD n = ::GetEnvironmentVariable(_T("LOCALAPPDATA"), base, MAX_PATH);
	CString root;
	if (n > 0 && n < MAX_PATH)
		root = base;
	else {
		// LOCALAPPDATA が取れない稀な環境: TEMP 配下へ(消されやすいが書込はできる)
		TCHAR tmp[MAX_PATH] = {};
		if (::GetTempPath(MAX_PATH, tmp) == 0 || tmp[0] == 0)
			return CString();
		root = tmp;
		// GetTempPath は末尾 \ 付き
		while (!root.IsEmpty() && (root[root.GetLength() - 1] == _T('\\') || root[root.GetLength() - 1] == _T('/')))
			root = root.Left(root.GetLength() - 1);
	}
	CString app = root + _T("\\oggYSED");
	CString dir = app + _T("\\resume");
	::CreateDirectory(app, NULL);
	::CreateDirectory(dir, NULL);
	return dir;
}

// 新規保存先(常に LocalAppData 側)
static CString ResumeSavePathNew(LPCTSTR mediaPath)
{
	if (!mediaPath || !*mediaPath) return CString();
	CString dir = ResumeSaveDir();
	if (dir.IsEmpty()) return CString();
	CString path;
	path.Format(_T("%s\\%016I64X.save"), (LPCTSTR)dir, ResumeSaveHashPath(mediaPath));
	return path;
}

static CString ResumeSavePathLegacy(LPCTSTR mediaPath)
{
	if (!mediaPath || !*mediaPath) return CString();
	return CString(mediaPath) + _T(".save");
}

static BOOL ResumeSaveFileExists(LPCTSTR path)
{
	if (!path || !*path) return FALSE;
	const DWORD a = ::GetFileAttributes(path);
	return (a != INVALID_FILE_ATTRIBUTES) && !(a & FILE_ATTRIBUTE_DIRECTORY);
}

// 読込用: 新場所優先、無ければ旧サイドカー
static CString ResumeSavePathRead(LPCTSTR mediaPath)
{
	CString neu = ResumeSavePathNew(mediaPath);
	if (ResumeSaveFileExists(neu))
		return neu;
	CString leg = ResumeSavePathLegacy(mediaPath);
	if (ResumeSaveFileExists(leg))
		return leg;
	return neu; // どちらも無い → Open は失敗(存在チェック用途)
}

static void ResumeSaveRemove(LPCTSTR mediaPath)
{
	CString neu = ResumeSavePathNew(mediaPath);
	if (!neu.IsEmpty() && ResumeSaveFileExists(neu)) {
		try { CFile::Remove(neu); }
		catch (...) {}
	}
	CString leg = ResumeSavePathLegacy(mediaPath);
	if (!leg.IsEmpty() && ResumeSaveFileExists(leg)) {
		try { CFile::Remove(leg); }
		catch (...) {}
	}
}

static void ResumeSaveRemoveLegacyOnly(LPCTSTR mediaPath)
{
	CString leg = ResumeSavePathLegacy(mediaPath);
	if (!leg.IsEmpty() && ResumeSaveFileExists(leg)) {
		try { CFile::Remove(leg); }
		catch (...) {}
	}
}

// playb(__int64) で途中位置を持つ形式(動画DShow以外の内蔵再生)
static BOOL ResumeModeUsesPlayb(int m)
{
	if (m == -10 || m == -9 || m == -8 || m == -7 || m == -6 || m == 34 || m == 35 || m == -1 || m == 999 || m == -3 || m == 30)
		return TRUE;
	if (m >= 1 && m <= 21) return TRUE;
	if (m == -11 || m == -12 || m == -13 || m == -14 || m == -15) return TRUE;
	return FALSE;
}

// mid/プロジェクトは KPI/VST 再生になり、mode=-2 に落ちない。
// 旧仕様で -2 に落ちていた頃の DShow 途中保存が残っていても効かせない。
static BOOL IsMidiOrProjectMedia(LPCTSTR path)
{
	if (!path || !*path) return FALSE;
	return (VstIsMidiExt(path) || VstIsProjectExt(path)) ? TRUE : FALSE;
}

static BOOL ResumeDshowApplies(int m, LPCTSTR path)
{
	if (m != -2) return FALSE;
	if (IsMidiOrProjectMedia(path)) return FALSE;
	return TRUE;
}

// 動画グラフ構築(play/plays)の前に呼ぶ。.save が無ければ 0。
// g_resumeSilentArm: 0=未指定 / 1=はい(途中から) / 2=いいえ(先頭から・save削除) / 3=先頭から(save残す)
static volatile LONG g_resumeSilentArm = 0;
static volatile LONG g_inResumePrompt = 0;
static volatile LONG g_inDougaTeardown = 0;
extern int mode;

void OggArmRemoteSilentResumeYes()
{
	InterlockedExchange(&g_resumeSilentArm, 1);
}

void OggArmRemoteSilentResumeNo()
{
	InterlockedExchange(&g_resumeSilentArm, 2);
}

void OggArmResumeFromStartKeepSave()
{
	InterlockedExchange(&g_resumeSilentArm, 3);
}

static volatile LONG g_resumePromptPosted = 0;
static CString g_resumePromptPath;

static HWND ResumePromptTargetHwnd()
{
	extern CMediaPlayerDlg* mp;
	if (mp && ::IsWindow(mp->GetSafeHwnd()))
		return mp->GetSafeHwnd();
	if (og && ::IsWindow(og->GetSafeHwnd()))
		return og->GetSafeHwnd();
	return NULL;
}

static void ResumePromptKillQueued()
{
	MSG m;
	extern CMediaPlayerDlg* mp;
	if (mp && ::IsWindow(mp->GetSafeHwnd())) {
		::KillTimer(mp->GetSafeHwnd(), IDT_OGG_RESUME_PROMPT);
		::KillTimer(mp->GetSafeHwnd(), IDT_OGG_RESUME_RESTART);
		while (::PeekMessage(&m, mp->GetSafeHwnd(), WM_OGG_RESUME_PROMPT, WM_OGG_RESUME_PROMPT, PM_REMOVE)) {}
	}
	if (og && ::IsWindow(og->GetSafeHwnd())) {
		::KillTimer(og->GetSafeHwnd(), IDT_OGG_RESUME_PROMPT);
		::KillTimer(og->GetSafeHwnd(), IDT_OGG_RESUME_RESTART);
		while (::PeekMessage(&m, og->GetSafeHwnd(), WM_OGG_RESUME_PROMPT, WM_OGG_RESUME_PROMPT, PM_REMOVE)) {}
	}
}

static void ResumeDrainQueuedKeyDowns()
{
	MSG msg;
	while (::PeekMessage(&msg, NULL, WM_KEYDOWN, WM_KEYUP, PM_REMOVE)) {}
	while (::PeekMessage(&msg, NULL, WM_SYSKEYDOWN, WM_SYSKEYUP, PM_REMOVE)) {}
	while (::PeekMessage(&msg, NULL, WM_CHAR, WM_DEADCHAR, PM_REMOVE)) {}
}

// Space の KEYDOWN 中に MessageBox すると同じキーではいが押されるため、
// ここでは投稿するだけ。TRUE=再生してよい / FALSE=確認待ち or キャンセル。
BOOL OggPrepareResumeBeforePlayback(LPCTSTR mediaPath)
{
	if (InterlockedCompareExchange(&g_inDougaTeardown, 0, 0) != 0)
		return FALSE;
	if (!mediaPath || !*mediaPath) return TRUE;
	// mid は DShow 途中保存の対象外。内蔵(savecheck_mp3)がOFFなら確認も出さない。
	if (IsMidiOrProjectMedia(mediaPath) && !savedata.savecheck_mp3)
		return TRUE;
	if (!savedata.savecheck && !savedata.savecheck_mp3 && !savedata.savecheck_dshow)
		return TRUE;
	CString path = ResumeSavePathRead(mediaPath);
	if (!ResumeSaveFileExists(path)) return TRUE;
	const LONG already = InterlockedCompareExchange(&g_resumeSilentArm, 0, 0);
	if (already == 1 || already == 2 || already == 3)
		return TRUE;
	if (OggIsResumePromptActive())
		return FALSE;
	if (InterlockedCompareExchange(&g_resumePromptPosted, 1, 0) != 0)
		return FALSE;
	g_resumePromptPath = mediaPath;
	HWND h = ResumePromptTargetHwnd();
	BOOL queued = FALSE;
	if (h) {
		if (::PostMessage(h, WM_OGG_RESUME_PROMPT, 0, 0))
			queued = TRUE;
		if (::SetTimer(h, IDT_OGG_RESUME_PROMPT, 30, NULL))
			queued = TRUE;
	}
	if (!queued) {
		InterlockedExchange(&g_resumePromptPosted, 0);
		OggRunResumePrompt();
	}
	return FALSE;
}

// play/OnRestart 内ではダイアログを出さない（動画グラフ構築中の MessageBox で固まる）
static int PromptResumePlaybackIfSaveExists(CWnd* wnd, LPCTSTR mediaPath)
{
	UNREFERENCED_PARAMETER(wnd);
	if (!mediaPath || !*mediaPath) return 0;
	// mid + DShow専用チェックのみ → 確認しない（旧 -2 落ち時代の .save も無視）
	if (IsMidiOrProjectMedia(mediaPath) && !savedata.savecheck_mp3)
		return 0;
	if (ResumeDshowApplies(mode, mediaPath) && savedata.savecheck_dshow != 1)
		return 0;
	if (ResumeModeUsesPlayb(mode) && savedata.savecheck_mp3 != 1)
		return 0;
	CString path = ResumeSavePathRead(mediaPath);
	if (!ResumeSaveFileExists(path)) return 0;
	const LONG arm = InterlockedExchange(&g_resumeSilentArm, 0);
	if (arm == 2) {
		ResumeSaveRemove(mediaPath);
		return 0;
	}
	if (arm == 3)
		return 0;
	if (OggIsResumePromptActive())
		return 0;
	// arm==1（はい）または未確認の自動再開: 途中から（位置を捨てない）
	return 1;
}

// plays2 のあと Run。Run 完了まで待つ（待たずに抜けると Paused のまま
// 1 枚目だけ表示され、映像も音も出ない環境がある）
static void TryRunMediaControlQuick(BOOL armPitchCb = TRUE)
{
	extern IMediaControl* pMediaControl;
	extern CDouga* pMainFrame1;
	extern int ps;
	if (!pMediaControl) return;
	ps = 0;
	if (og && ::IsWindow(og->GetSafeHwnd()))
		og->ResetPauseButtonUi();

	if (armPitchCb)
		DougaPitchCorrect_EnableCallback();

	pMediaControl->Run();

	if (pMainFrame1 && ::IsWindow(pMainFrame1->GetSafeHwnd())) {
		if (!::IsWindowVisible(pMainFrame1->GetSafeHwnd()))
			pMainFrame1->ShowWindow(SW_SHOWNORMAL);
		pMainFrame1->RefreshVideoSizeAfterRun();
		pMainFrame1->ApplyVideoDest();
	}
}

static void DougaRunThenSeek(double seekSec)
{
	extern CDouga* pMainFrame1;
	extern IGraphBuilder* pGraphBuilder;
	if (!pMainFrame1 || !pGraphBuilder)
		return;
	if (seekSec > 0.0)
		pMainFrame1->seek((LONGLONG)(((float)((float)seekSec * 100.0f * 100000.0f))));
	TryRunMediaControlQuick(TRUE);
}

