static BOOL ResumePlaybAtEndOrStart()
{
	extern __int64 playb;
	extern int oggsize;
	if (playb == 0) return TRUE;
	if (oggsize > 0 && playb >= (__int64)oggsize) return TRUE;
	return FALSE;
}

