// TOPMOST の KPI 読み込み窓が MessageBox のボタンを覆うのを防ぐ。
static int OggKpiAfxMessageBox(LPCTSTR text, UINT type)
{
	CKpiLoadingWnd* load = g_pActiveLoadingWnd;
	HWND hLoad = (load && load->GetSafeHwnd()) ? load->GetSafeHwnd() : NULL;
	const BOOL wasVisible = (hLoad != NULL && ::IsWindowVisible(hLoad));
	if (wasVisible)
		::ShowWindow(hLoad, SW_HIDE);

	const int ans = AfxMessageBox(text, type | MB_SETFOREGROUND | MB_TOPMOST);

	if (wasVisible && hLoad && ::IsWindow(hLoad)) {
		::ShowWindow(hLoad, SW_SHOW);
		::SetWindowPos(hLoad, HWND_TOPMOST, 0, 0, 0, 0,
			SWP_NOMOVE | SWP_NOSIZE | SWP_NOACTIVATE);
	}
	return ans;
}

// confirm=TRUE で確認ダイアログ。startupEmpty=TRUE のとき「いいえ」で再尋ねないフラグを保存。
// reloadAfter=TRUE のとき展開後に plug+KPI適用（起動時 plug 内からは FALSE）。
BOOL OggKpiDownloadPlugins(CWnd* owner, BOOL confirm, BOOL startupEmpty, BOOL reloadAfter)
{
#if WIN64
	UNREFERENCED_PARAMETER(owner);
	UNREFERENCED_PARAMETER(confirm);
	UNREFERENCED_PARAMETER(startupEmpty);
	UNREFERENCED_PARAMETER(reloadAfter);
	return FALSE;
#else
	if (confirm) {
		const int ans = OggKpiAfxMessageBox(OggKpiAskDownloadMsg(), MB_YESNO | MB_ICONQUESTION);
		if (ans != IDYES) {
			if (startupEmpty) {
				savedata.kpi_plugin_dl_skip = 1;
				MpPersistSavedataQuick();
			}
			return FALSE;
		}
	}

	CKpiLoadingWnd localWnd;
	CKpiLoadingWnd* wnd = g_pActiveLoadingWnd;
	BOOL ownWnd = FALSE;
	if (!wnd || !wnd->GetSafeHwnd()) {
		localWnd.Create(owner);
		localWnd.Show();
		wnd = &localWnd;
		g_pActiveLoadingWnd = wnd;
		ownWnd = TRUE;
		g_oggKpiLoading = 1;
	}

	OggKpiLoadingProgressPct(0, wnd);
	CString err;
	const BOOL ok = KpiInstall_DownloadAndExtract(karento2, OggKpiLoadingProgressPct, wnd, err);
	if (!ok) {
		if (err.IsEmpty()) {
			err = LL14(L"KPIプラグインの取得に失敗しました。", L"Failed to obtain KPI plugins.",
				L"Echec de l'obtention des plugins KPI.", L"Acquisizione plugin KPI non riuscita.",
				L"Fallo al obtener plugins KPI.", L"KPI 플러그인 확보 실패.", L"获取 KPI 插件失败。",
				L"فشل الحصول على إضافات KPI.", L"Не удалось получить KPI-плагины.",
				L"KPI-Plugins konnten nicht geholt werden.", L"Falha ao obter plugins KPI.",
				L"KPI-plugins ophalen mislukt.", L"Nie udalo sie pobrac wtyczek KPI.",
				L"KPI eklentileri alinamadi.");
		}
		OggKpiAfxMessageBox(err, MB_ICONERROR);
	} else if (reloadAfter) {
		wnd->SetStatusText(LL14(
			L"プラグイン読み込み中…\n（ダウンロード完了・再読込）",
			L"Loading plugins…\n(Download done — reloading)",
			L"Chargement plugins…\n(Telechargement OK — relecture)",
			L"Caricamento plugin…\n(Download OK — ricarica)",
			L"Cargando plugins…\n(Descarga OK — recarga)",
			L"플러그인 읽는 중…\n(다운로드 완료·다시 읽기)",
			L"正在读取插件…\n（下载完成·重新加载）",
			L"تحميل الإضافات…\n(اكتمل التنزيل — إعادة)",
			L"Загрузка плагинов…\n(Загрузка OK — перечитывание)",
			L"Plugins laden…\n(Download fertig — neu laden)",
			L"A carregar plugins…\n(Download OK — a recarregar)",
			L"Plugins laden…\n(Download klaar — herladen)",
			L"Wczytywanie wtyczek…\n(Pobrano — ponowne wczytanie)",
			L"Eklentiler yükleniyor…\n(Indirme bitti — yeniden)"));
		g_nCurrentKpiIndex = 0;
		if (og && ::IsWindow(og->GetSafeHwnd()))
			og->plug(karento2, NULL);
		OggKpiApplyAfterPlug();
	} else if (wnd) {
		wnd->SetStatusText(LL14(
			L"プラグイン読み込み中…\n（しばらく時間がかかる場合があります）",
			L"Loading plugins…\n(This may take some time)",
			L"Chargement des plugins…\n(Cela peut prendre du temps)",
			L"Caricamento plugin…\n(Questo potrebbe richiedere del tempo)",
			L"Cargando plugins…\n(Esto puede tardar un poco)",
			L"플러그인 읽는 중…\n(시간이 다소 걸릴 수 있습니다)",
			L"正在读取插件…\n（可能需要一些时间）",
			L"جاري تحميل الإضافات…\n(قد يستغرق هذا بعض الوقت)",
			L"Загрузка плагинов…\n(Это может занять некоторое время)",
			L"Plugins werden geladen…\n(Dies kann einige Zeit dauern)",
			L"A carregar plugins…\n(Isso pode levar algum tempo)",
			L"Plugins laden…\n(Dit kan even duren)",
			L"Wczytywanie wtyczek…\n(Może to zająć trochę czasu)",
			L"Eklentiler yükleniyor…\n(Bu biraz zaman alabilir)"));
	}

	if (ownWnd) {
		g_pActiveLoadingWnd = NULL;
		g_oggKpiLoading = 0;
		localWnd.DestroyWindow();
		COgg_KickTimerp();
	}
	return ok;
#endif
}

BOOL OggKpiReloadPlugins(CWnd* owner)
{
#if WIN64
	UNREFERENCED_PARAMETER(owner);
	return FALSE;
#else
	if (!og || !::IsWindow(og->GetSafeHwnd()))
		return FALSE;

	CKpiLoadingWnd localWnd;
	CKpiLoadingWnd* wnd = g_pActiveLoadingWnd;
	BOOL ownWnd = FALSE;
	if (!wnd || !wnd->GetSafeHwnd()) {
		localWnd.Create(owner);
		localWnd.Show();
		wnd = &localWnd;
		g_pActiveLoadingWnd = wnd;
		ownWnd = TRUE;
		g_oggKpiLoading = 1;
	}
	wnd->SetStatusText(LL14(
		L"プラグイン読み込み中…\n（再読込）",
		L"Loading plugins…\n(Reload)",
		L"Chargement plugins…\n(Relecture)",
		L"Caricamento plugin…\n(Ricarica)",
		L"Cargando plugins…\n(Recarga)",
		L"플러그인 읽는 중…\n(다시 읽기)",
		L"正在读取插件…\n（重新加载）",
		L"تحميل الإضافات…\n(إعادة)",
		L"Загрузка плагинов…\n(Перечитывание)",
		L"Plugins laden…\n(Neu laden)",
		L"A carregar plugins…\n(Recarregar)",
		L"Plugins laden…\n(Herladen)",
		L"Wczytywanie wtyczek…\n(Ponowne wczytanie)",
		L"Eklentiler yükleniyor…\n(Yeniden)"));
	g_nCurrentKpiIndex = 0;
	og->plug(karento2, NULL);
	OggKpiApplyAfterPlug();
	if (ownWnd) {
		g_pActiveLoadingWnd = NULL;
		g_oggKpiLoading = 0;
		localWnd.DestroyWindow();
		COgg_KickTimerp();
	}
	return TRUE;
#endif
}

double aa1_ = 0;
BOOL CAboutDlg::OnInitDialog()
{
	CCustomBlurDialogBase::OnInitDialog();

	SetWindowText(LL14(L"oggのバージョン情報", L"ogg Version Info", L"Info version ogg", L"Info versione ogg", L"Info version ogg", L"ogg 버전 정보", L"ogg版本信息", L"معلومات إصدار ogg", L"Информация о версии ogg", L"ogg Versionsinfo", L"Info versao ogg", L"ogg versie-info", L"Informacje o wersji ogg", L"ogg surum bilgisi"));
	SetDlgItemText(IDOK, LL14(L"OK", L"OK", L"OK", L"OK", L"OK", L"확인", L"确定", L"موافق", L"OK", L"OK", L"OK", L"OK", L"OK", L"Tamam"));
	COSVersion os;
	CString s;
	s.Format(_T("%s"), os.GetVersionString());

	m_in.SetWindowText(s);


	char CPUBrandString[0x40];
	int CPUInfo[4] = { -1 };
	__cpuid(CPUInfo, 0x80000002);
	memcpy(CPUBrandString, CPUInfo, sizeof(CPUInfo));
	__cpuid(CPUInfo, 0x80000003);
	memcpy(CPUBrandString + 16, CPUInfo, sizeof(CPUInfo));
	__cpuid(CPUInfo, 0x80000004);
	memcpy(CPUBrandString + 32, CPUInfo, sizeof(CPUInfo));
	s = CPUBrandString;
	m_cpu.SetWindowText(s);

	if (og && ::IsWindow(og->GetSafeHwnd()))
		og->m_os3.GetWindowText(s);
	else
		s = BuildCpuInstructionListString();
	m_os3.SetWindowText(s);
	m_os3.SetReadOnly(TRUE);

	// 性能パネル: プレースホルダ矩形を DPI 密に最大化して載せ替え
	CWnd* pPh = GetDlgItem(IDC_ABOUT_PERF);
	CWnd* pLink = GetDlgItem(IDC_Link);
	if (pPh && ::IsWindow(pPh->GetSafeHwnd())) {
		CRect rcClient;
		GetClientRect(&rcClient);
		CRect rcPh;
		pPh->GetWindowRect(&rcPh);
		ScreenToClient(&rcPh);
		CRect rcLink;
		int linkH = 0;
		if (pLink && ::IsWindow(pLink->GetSafeHwnd())) {
			pLink->GetWindowRect(&rcLink);
			ScreenToClient(&rcLink);
			linkH = rcLink.Height();
			if (linkH < 1) linkH = 12;
		}
		HDC hdc = ::GetDC(m_hWnd);
		const UINT dpi = hdc ? (UINT)GetDeviceCaps(hdc, LOGPIXELSX) : 96;
		if (hdc) ::ReleaseDC(m_hWnd, hdc);
		const int pad = MulDiv(4, (int)(dpi ? dpi : 96), 96);
		const int gap = MulDiv(2, (int)(dpi ? dpi : 96), 96);
		rcPh.left = rcClient.left + pad;
		rcPh.right = rcClient.right - pad;
		rcPh.bottom = rcClient.bottom - pad - linkH - gap;
		if (rcPh.bottom < rcPh.top + MulDiv(120, (int)(dpi ? dpi : 96), 96))
			rcPh.bottom = rcPh.top + MulDiv(120, (int)(dpi ? dpi : 96), 96);
		pPh->DestroyWindow();
		m_perf.Create(WS_CHILD | WS_VISIBLE | WS_CLIPSIBLINGS, rcPh, this, IDC_ABOUT_PERF);
		if (pLink && ::IsWindow(pLink->GetSafeHwnd())) {
			const int ly = rcClient.bottom - pad - linkH;
			pLink->MoveWindow(rcPh.left + MulDiv(33, (int)(dpi ? dpi : 96), 96), ly, rcPh.Width() - MulDiv(33, (int)(dpi ? dpi : 96), 96), linkH, TRUE);
		}
#if CCUSTOM_AERO_SUPPORT
		m_perf.SetAeroMode(CCC_IsAeroEnabled());
#endif
	}

	CCC_BringDialogToForeground(this);
	return TRUE;  // return TRUE unless you set the focus to a control
	// 例外 : OCX プロパティ ページは必ず FALSE を返します。
}

