void MpPushPlayHistory(LPCTSTR path, LPCTSTR displayName)
{
	if (!path || !*path) return;
	CString p = NormalizePlaylistPath(path);
	if (p.IsEmpty()) p = path;
	p.Trim();
	CString n(displayName ? displayName : _T(""));
	n.Trim();
	if (p.IsEmpty()) return;
	if (n.IsEmpty()) {
		int slash = p.ReverseFind(_T('\\'));
		n = (slash >= 0) ? p.Mid(slash + 1) : p;
	}

	int plIdx = -1;
	int mode = 0;
	int r2 = 0;
	extern int plcnt;
	extern int modesub;
	extern int ret2;
	if (pl && pl->pc && pl->playcnt > 0) {
		if (plcnt >= 0 && plcnt < pl->playcnt
			&& NormalizePlaylistPath(pl->pc[plcnt].fol).CompareNoCase(p) == 0) {
			plIdx = plcnt;
			mode = pl->pc[plcnt].sub;
			r2 = pl->pc[plcnt].ret2;
		}
		else {
			for (int i = 0; i < pl->playcnt; ++i) {
				if (NormalizePlaylistPath(pl->pc[i].fol).CompareNoCase(p) == 0) {
					plIdx = i;
					mode = pl->pc[i].sub;
					r2 = pl->pc[i].ret2;
					break;
				}
			}
		}
	}
	if (plIdx < 0) {
		mode = modesub;
		r2 = ret2;
	}

	MpHist_Push(p, n, plIdx);
	MpPersistSavedataQuick();
	ProAudio_BumpPlayCount(SongParams_CurrentListName(), p, mode, r2);

	if (savedata.playerMode == 1)
		RefreshTaskbarJumpList(TRUE);
	if (mp && ::IsWindow(mp->GetSafeHwnd()) && savedata.mpHistOpen)
		mp->HistRebuildList();
}

static volatile LONG s_restartMsgQueued = 0;
static volatile LONG s_restartWanted = 0;
static volatile LONG s_onRestartBusy = 0;
// 二重DS昇格の soft play() 実行中。この間の Restart 再キューは頭出しデグレの原因なので捨てる。
// Promote で確定したスキップ。atomic が消えても play() で頭出ししない。

BOOL OggIsResumePromptActive()
{
	return InterlockedCompareExchange(&g_inResumePrompt, 0, 0) != 0 ? TRUE : FALSE;
}

void OggCancelPendingPlaybackRestart()
{
	InterlockedExchange(&s_restartWanted, 0);
	InterlockedExchange(&s_restartMsgQueued, 0);
	if (og && ::IsWindow(og->GetSafeHwnd())) {
		MSG m;
		while (::PeekMessage(&m, og->GetSafeHwnd(), WM_APP + 2, WM_APP + 2, PM_REMOVE)) {}
	}
}

// WM_APP+2(再演奏)を 1 件にまとめる。リストで曲を連打しても stop/play が直列に
// 何十回も走らないようにする(キュー溜めによる UI 固まり対策)。
void RequestPlaybackRestart(HWND hwnd)
{
	if (OggIsResumePromptActive())
		return;
	if (InterlockedCompareExchange(&s_onRestartBusy, 0, 0) != 0)
		return;
	if (!hwnd) {
		if (og && ::IsWindow(og->GetSafeHwnd()))
			hwnd = og->GetSafeHwnd();
	}
	if (!hwnd || !::IsWindow(hwnd))
		return;
	InterlockedExchange(&s_restartWanted, 1);
	if (InterlockedCompareExchange(&s_restartMsgQueued, 1, 0) == 0)
		::PostMessage(hwnd, WM_APP + 2, 0, 0);
}

// タグ書込前: 現位置をメモリに残し、次の play() で確認なしシークする。
// ※ stop1→OnRestart→stop() が playb==0 で .save を消すため、ファイル頼みにしない。
static volatile LONG g_silentResumeApply = 0;
static __int64 g_silentResumePlayb = 0;
static double g_silentResumeAa = 0.0;

void OggArmSilentResumeFromCurrent()
{
	extern __int64 playb;
	extern double aa1_;
	extern double oggsize2;
	extern CString filen;
	extern int mode;
	if (filen.IsEmpty()) {
		InterlockedExchange(&g_silentResumeApply, 0);
		return;
	}
	if (!ResumeModeUsesPlayb(mode) && !ResumeDshowApplies(mode, filen)) {
		InterlockedExchange(&g_silentResumeApply, 0);
		return;
	}

	BOOL atBoundary = FALSE;
	if (ResumeModeUsesPlayb(mode) && ResumePlaybAtEndOrStart())
		atBoundary = TRUE;
	if (ResumeDshowApplies(mode, filen)) {
		if (aa1_ == 0.0) atBoundary = TRUE;
		if (oggsize2 > 0.0 && aa1_ >= oggsize2) atBoundary = TRUE;
	}
	if (atBoundary) {
		InterlockedExchange(&g_silentResumeApply, 0);
		g_silentResumePlayb = 0;
		g_silentResumeAa = 0.0;
		return;
	}
	g_silentResumePlayb = playb;
	g_silentResumeAa = aa1_;
	InterlockedExchange(&g_silentResumeApply, 1);
}

extern BOOL changeflg;

// apply=0: 同じリスト内のみ（クロスフェード用。リスト切替はしない）
// apply=1: 終端モードに従い次リストへ Load する
static int PlaylistResolveNextIndex(int nextBtn, int apply)
{
	if (!pl) return -1;
	int n = pl->playcnt;
	int cur = plcnt;
	if (cur < 0) cur = 0;

	if (savedata.mpListRandom && n > 1) {
		int next = cur;
		int t = 0;
		unsigned mix = (unsigned)rand() ^ ((unsigned)rand() << 15);
		do {
			mix = mix * 1103515245u + 12345u;
			next = (int)(mix % (unsigned)n);
			t++;
		} while (next == cur && t < 64);
		return next;
	}

	if (n > 0) {
		int next = cur + 1;
		if (next < n) return next;
	}

	int em = savedata.plEndMode;
	if (em < 0 || em > 3) em = 1;
	if (nextBtn && em == 0) em = 1;
	if (em == 0) return -1;
	if (em == 1) return (n > 0) ? 0 : -1;
	if (pl->m_tempMode) return (n > 0) ? 0 : -1;
	if (!apply) return -1;

	int npl = pl->GetPlaylistFileCount();
	if (npl <= 0) return (n > 0) ? 0 : -1;
	int startPl = savedata.playlistnum;
	int np = startPl;
	for (int guard = 0; guard < npl; guard++) {
		np++;
		if (np >= npl) {
			if (em == 2) return -1;
			np = 0;
		}
		if (np == startPl) return (n > 0) ? 0 : -1;
		if (pl->pc != NULL && pl->playcnt > 0)
			pl->Save();
		savedata.playlistnum = np;
		pl->playcnt = 0;
		pl->pnt = -1;
		pl->pnt1 = -1;
		free(pl->pc);
		pl->pc = NULL;
		pl->Load(FALSE);
		if (pl->pc == NULL)
			pl->pc = (playlistdata0*)malloc(sizeof(playlistdata0));
		pl->m_lc.SetItemCount(pl->playcnt);
		for (int j = 0; j < pl->playcnt; j++)
			pl->pc[j].icon = 1;
		changeflg = TRUE;
		pl->loadplaylistname();
		changeflg = FALSE;
		extern CMediaPlayerDlg* mp;
		if (mp && ::IsWindow(mp->GetSafeHwnd())) {
			mp->ReloadPlaylistCombo();
			mp->RefreshList(TRUE);
		}
		if (pl->playcnt > 0) {
			if (savedata.mpListRandom && pl->playcnt > 1) {
				unsigned mix = (unsigned)rand() ^ ((unsigned)rand() << 15);
				return (int)(mix % (unsigned)pl->playcnt);
			}
			return 0;
		}
	}
	return -1;
}

static int PlaylistGoNext(int doRestart, int nextBtn)
{
	extern CMediaPlayerDlg* mp;
	if (doRestart && mp && ::IsWindow(mp->GetSafeHwnd()) && mp->TryPlayFromQueue())
		return 1;
	int next = PlaylistResolveNextIndex(nextBtn, 1);
	if (next < 0) {
		if (doRestart && og && ::IsWindow(og->GetSafeHwnd()))
			og->SendMessage(WM_COMMAND, MAKEWPARAM(IDC_BUTTON1, BN_CLICKED), 0);
		return 0;
	}
	if (!pl || next >= pl->playcnt) return 0;
	plcnt = next;
	pl->Get(plcnt);
	pl->SIcon(plcnt);
	gameon = 0;
	if (doRestart && og && ::IsWindow(og->GetSafeHwnd())) {
		if (pl->pc)
			MpPushPlayHistory(pl->pc[next].fol, pl->pc[next].name);
		RequestPlaybackRestart(og->GetSafeHwnd());
	}
	return 1;
}

static DWORD g_kpiRenzokuTick = 0;
static int   g_kpiRenzokuPnt = -999;
static const DWORD KPI_RENZOKU_LIMIT_MS = 300000;

static void RenzokuFadeOrXfade()
{
	if (fadeadd != 0.0f) return;
	if (InterlockedCompareExchange(&g_xfInProgress, 0, 0)) return;
	g_kpiRenzokuTick = 0;
	g_kpiRenzokuPnt = -999;
	if (XfEnabled() && XfStartCrossfadeFromNotify())
		return;
	if (og && ::IsWindow(og->GetSafeHwnd()))
		og->SendMessage(WM_COMMAND, MAKEWPARAM(IDC_BUTTON5, BN_CLICKED), 0);
}

static int MpCurrentPlayIndex()
{
	if (!pl || pl->playcnt <= 0) return -1;
	if (pl->pnt >= 0 && pl->pnt < pl->playcnt) return pl->pnt;
	if (plcnt >= 0 && plcnt < pl->playcnt) return plcnt;
	return 0;
}

void MpTaskbarReplay()
{
	if (pl && pl->playcnt > 0)
		pl->RestoreSavedPlaybackRow();
	extern CString filen;
	if (!OggPrepareResumeBeforePlayback(filen))
		return;
	if (og && ::IsWindow(og->GetSafeHwnd()))
		RequestPlaybackRestart(og->GetSafeHwnd());
}

void MpTaskbarNextTrack()
{
	PlaylistGoNext(1, 1);
}

void MpTaskbarPrevTrack()
{
	extern UINT ttt;
	extern int plf;
	extern int ps;
	extern double aa1_;
	extern int mode;
	extern BOOL videoonly;
	extern IMediaControl* pMediaControl;
	extern IMediaPosition* pMediaPosition;
	const BOOL videoMode = (mode == -2 || videoonly);
	double posSec = aa1_;
	if (videoMode && pMediaPosition) {
		REFTIME aa = 0;
		if (SUCCEEDED(pMediaPosition->get_CurrentPosition(&aa)) && aa > posSec)
			posSec = (double)aa;
	}
	// ttt は 1/100 秒。3秒以上なら途中保存を見ずに同じ項目を頭から（一時停止中も含む）
	const BOOL over3 = (ttt >= 300) || (posSec >= 3.0);
	BOOL fromStart = FALSE;
	if (plf && over3)
		fromStart = TRUE;
	// 窓は出たがグラフが走っていない（他環境の無再生）→ 同じ動画を頭からやり直し
	if (!fromStart && plf && videoMode && pMediaControl && ps != 1) {
		OAFilterState st = State_Stopped;
		pMediaControl->GetState(0, &st);
		if (st != State_Running)
			fromStart = TRUE;
	}
	if (fromStart || ((!pl || pl->playcnt <= 0) && plf)) {
		OggArmResumeFromStartKeepSave();
		if (og && ::IsWindow(og->GetSafeHwnd()))
			RequestPlaybackRestart(og->GetSafeHwnd());
		return;
	}
	if (!pl || pl->playcnt <= 0) return;
	int idx = MpCurrentPlayIndex();
	if (idx < 0) idx = 0;
	else {
		idx--;
		if (idx < 0) idx = pl->playcnt - 1;
	}
	pl->Get(idx);
	plcnt = idx;
	gameon = 0;
	MpPushPlayHistory(pl->pc[idx].fol, pl->pc[idx].name);
	if (og && ::IsWindow(og->GetSafeHwnd()))
		RequestPlaybackRestart(og->GetSafeHwnd());
}

static BOOL MpPlayExistingPlaylistPath(LPCTSTR path)
{
	if (!pl) return FALSE;
	const int idx = pl->FindByPath(path);
	if (idx < 0) return FALSE;
	pl->Get(idx);
	plcnt = idx;
	gameon = 0;
	MpPushPlayHistory(pl->pc[idx].fol, pl->pc[idx].name);
	if (mp && ::IsWindow(mp->GetSafeHwnd()))
		mp->FollowPlayingRow();
	if (!OggPrepareResumeBeforePlayback(pl->pc[idx].fol))
		return TRUE;
	if (og && ::IsWindow(og->GetSafeHwnd()))
		RequestPlaybackRestart(og->GetSafeHwnd());
	return TRUE;
}

// タスクバー: サムネイルツールバー(再生/停止等)とジャンプリスト(右クリック)をモード別に設定
void SetupTaskbarThumbButtons(HWND hwnd, BOOL mediaPlayerMode)
{
	if (!ptl || !hwnd || !::IsWindow(hwnd)) return;

	static BOOL s_hasThumbOg = FALSE;
	static BOOL s_hasThumbMp = FALSE;
	static HWND s_mpThumbHwnd = NULL;
	BOOL* pHas = &s_hasThumbOg;
	if (mp && ::IsWindow(mp->GetSafeHwnd()) && hwnd == mp->m_hWnd) {
		if (s_mpThumbHwnd != hwnd) { s_hasThumbMp = FALSE; s_mpThumbHwnd = hwnd; }
		pHas = &s_hasThumbMp;
	}

	THUMBBUTTON b[4];
	ZeroMemory(b, sizeof(b));
	b[0].hIcon = ::AfxGetApp()->LoadIcon(IDI_T1); b[0].dwMask = THB_ICON | THB_TOOLTIP | THB_FLAGS;
	b[0].dwFlags = THBF_ENABLED; b[0].iId = 0;
	wcscpy(b[0].szTip, L"再演奏");
	b[1].hIcon = ::AfxGetApp()->LoadIcon(IDI_T2); b[1].dwMask = THB_ICON | THB_TOOLTIP | THB_FLAGS;
	b[1].dwFlags = THBF_ENABLED; b[1].iId = 1;
	wcscpy(b[1].szTip, L"一時停止");
	b[2].hIcon = ::AfxGetApp()->LoadIcon(IDI_T3); b[2].dwMask = THB_ICON | THB_TOOLTIP | THB_FLAGS;
	b[2].dwFlags = THBF_ENABLED; b[2].iId = 2;
	wcscpy(b[2].szTip, L"停止");
	b[3].hIcon = ::AfxGetApp()->LoadIcon(IDI_T4); b[3].dwMask = THB_ICON | THB_TOOLTIP | THB_FLAGS;
	b[3].dwFlags = THBF_ENABLED; b[3].iId = 3;
	if (mediaPlayerMode)
		wcscpy(b[3].szTip, L"次の曲");
	else
		wcscpy(b[3].szTip, L"プレイリスト開閉");

	if (*pHas)
		ptl->ThumbBarUpdateButtons(hwnd, 4, b);
	else if (SUCCEEDED(ptl->ThumbBarAddButtons(hwnd, 4, b)))
		*pHas = TRUE;
}

void RefreshTaskbarJumpList(BOOL mediaPlayerMode)
{
	if (!pcdl || !og) return;
	UINT cMinSlots;
	IObjectArray* poaRemoved = NULL;
	if (FAILED(pcdl->BeginList(&cMinSlots, IID_PPV_ARGS(&poaRemoved)))) return;

	IShellLink* psl = NULL;
	auto addHistLink = [&](IObjectCollection* pocHist, LPCTSTR arg, LPCTSTR title) -> bool {
		psl = NULL;
		og->_CreateShellLink((LPTSTR)arg, (LPTSTR)title, &psl, 0, true);
		if (!psl) return false;
		const HRESULT hr = pocHist->AddObject(psl);
		psl->Release();
		psl = NULL;
		return SUCCEEDED(hr);
	};

	// 最近再生した曲は Tasks とは別カテゴリ(ジャンプリスト上部)
	// 壊れた履歴パスはシェル側で ERROR_INVALID_PARAMETER になり得るためスキップ
	if (mediaPlayerMode && savedata.mpHistCnt > 0 && savedata.mpHistCnt <= 8) {
		IObjectCollection* pocHist = NULL;
		if (SUCCEEDED(CoCreateInstance(CLSID_EnumerableObjectCollection, NULL, CLSCTX_INPROC, IID_PPV_ARGS(&pocHist))) && pocHist) {
			UINT histAdded = 0;
			for (int hi = 0; hi < savedata.mpHistCnt && hi < 8; ++hi) {
				const TCHAR* path = savedata.mpHistPath[hi];
				if (!path || path[0] == 0) continue;
				const bool absDrive = (path[1] == _T(':')
					&& (path[2] == _T('\\') || path[2] == _T('/')));
				const bool absUnc = (path[0] == _T('\\') && path[1] == _T('\\'));
				if (!absDrive && !absUnc) continue;
				CString title = savedata.mpHistName[hi];
				if (title.IsEmpty()) title = path;
				if (title.GetLength() > 64)
					title = title.Left(61) + _T("...");
				if (addHistLink(pocHist, path, title))
					histAdded++;
			}
			if (histAdded > 0) {
				IObjectArray* poaHist = NULL;
				if (SUCCEEDED(pocHist->QueryInterface(IID_PPV_ARGS(&poaHist)))) {
					pcdl->AppendCategory(LL14(L"最近再生した曲", L"Recently played", L"Recemment ecoute", L"Riprodotti di recente", L"Reproducido recientemente", L"최근 재생", L"最近播放", L"التشغيلات الأخيرة", L"Недавно проигранные", L"Zuletzt gespielt", L"Reproduzido recentemente", L"Recent afgespeeld", L"Ostatnio odtwarzane", L"Son calinanlar"), poaHist);
					poaHist->Release();
				}
			}
			pocHist->Release();
		}
	}

	IObjectCollection* pocNew = NULL;
	CoCreateInstance(CLSID_EnumerableObjectCollection, NULL, CLSCTX_INPROC, IID_PPV_ARGS(&pocNew));
	if (!pocNew) { pcdl->AbortList(); if (poaRemoved) poaRemoved->Release(); return; }

	auto addLink = [&](LPCTSTR arg, LPCTSTR title) {
		psl = NULL;
		og->_CreateShellLink((LPTSTR)arg, (LPTSTR)title, &psl, 0, true);
		if (!psl) return;
		pocNew->AddObject(psl);
		psl->Release();
		psl = NULL;
	};
	auto addSep = [&]() {
		psl = NULL;
		og->_CreateShellLink(_T(""), _T(""), &psl, 0, true, FALSE);
		if (!psl) return;
		pocNew->AddObject(psl);
		psl->Release();
		psl = NULL;
	};

	addLink(_T("*1"), _T("再演奏"));
	addLink(_T("*2"), _T("一時停止"));
	addLink(_T("*3"), _T("停止"));
	addSep();
	if (mediaPlayerMode) {
		addLink(_T("*7"), LL14(L"次の曲", L"Next track", L"Piste suivante", L"Traccia succ.", L"Pista sig.", L"다음 곡", L"下一曲", L"التالي", L"Следующий", L"Naechster", L"Proxima", L"Volgende", L"Nastepny", L"Sonraki"));
		addLink(_T("*8"), LL14(L"前の曲", L"Previous track", L"Piste precedente", L"Traccia prec.", L"Pista ant.", L"이전 곡", L"上一曲", L"السابق", L"Предыдущий", L"Vorheriger", L"Anterior", L"Vorige", L"Poprzedni", L"Onceki"));
		addSep();
		addLink(_T("*9"), LL14(L"イコライザー", L"Equalizer", L"Egaliseur", L"Equalizzatore", L"Ecualizador", L"이퀄라이저", L"均衡器", L"المعادل", L"Эквалайзер", L"Equalizer", L"Equalizador", L"Equalizer", L"Korektor", L"Ekolayzer"));
		addLink(_T("*A"), LL14(L"ジャケット", L"Jacket art", L"Pochette", L"Copertina", L"Caratula", L"자켓", L"封面", L"الغلاف", L"Обложка", L"Cover", L"Capa", L"Hoes", L"Okładka", L"Kapak"));
	}
	else {
		addLink(_T("*4"), _T("プレイリスト開閉"));
	}
	addSep();
	addLink(_T("*5"), _T("レンダリング設定"));
	addLink(_T("*6"), _T("フォルダ設定"));

	IObjectArray* poa = NULL;
	if (SUCCEEDED(pocNew->QueryInterface(IID_PPV_ARGS(&poa)))) {
		pcdl->AddUserTasks(poa);
		poa->Release();
	}
	pcdl->CommitList();
	if (poaRemoved) poaRemoved->Release();
	pocNew->Release();
}


BOOL COggDlg::OnCommand(WPARAM wParam, LPARAM lParam)
{
	if (HIWORD(wParam) == THBN_CLICKED) {
		UINT CommandID = LOWORD(wParam);
		if (0 == CommandID)
			OnRestart();
		else if (1 == CommandID)
			OnPause();
		else if (2 == CommandID)
			stop();
		else if (3 == CommandID)
			OnPlayList();
	}
	return CCustomBlurDialogBase::OnCommand(wParam, lParam);
}

void COggDlg::OnSysCommand(UINT nID, LPARAM lParam)
{
	if ((nID & 0xFFF0) == IDM_ABOUTBOX)
	{
		CAboutDlg dlgAbout(this);
		dlgAbout.DoModal();
	}
	else
	{
		CCustomBlurDialogBase::OnSysCommand(nID, lParam);
	}
}

