// バナー値領域の総幅(4x px)。従来は固定ピッチ 5 文字ラベル(8*5)を差し引いて MDC としていた。
#define MDC_TOTAL ((88*2+170)*4)
#define MDC_LABEL_FIXED (8*5*4)
#define MDC (MDC_TOTAL - MDC_LABEL_FIXED)
#define MDCP (88*2+175)*4
// 相違メーター: 右端に φ/LR 縦積み。スペアナと隙間なく密着
#define BANNER_CORR_METER_W  72
#define BANNER_CORR_PAD      2   // バナー右端の余白のみ（スペアナ側の隙間は無し）
#define BANNER_CORR_RESERVE_PX (BANNER_CORR_METER_W + BANNER_CORR_PAD)

// もしダイアログボックスに最小化ボタンを追加するならば、アイコンを描画する
// コードを以下に記述する必要があります。MFC アプリケーションは document/view
// モデルを使っているので、この処理はフレームワークにより自動的に処理されます。

CImageBase* maini;
// システムは、ユーザーが最小化ウィンドウをドラッグしている間、
// カーソルを表示するためにここを呼び出します。
HCURSOR COggDlg::OnQueryDragIcon()
{
	return (HCURSOR)m_hIcon;
}

void COggDlg::Resize()
{
	// 折りたたみ時は ▲▼ / MP画面の下に十分な余白を残す(端すぎて押しにくい対策)
	const int kBottomPad = 12;
	const int kRightPad = 8;
	CString s;
	m_ue.GetWindowText(s);
	if (s == L"▼") {
		// 折りたたみ: 右パネルのグループ枠がはみ出して見えないように隠す
		m_ue.SetWindowText(_T("▲"));
		if (CWnd* g = GetDlgItem(IDC_OGG_GRP_MULTI))
			g->ShowWindow(SW_HIDE);
		if (CWnd* g = GetDlgItem(IDC_OGG_GRP_GAME))
			g->ShowWindow(SW_HIDE);
		CRect rect_1, rect_2;
		GetWindowRect(&rect_1);
		m_ue.GetWindowRect(&rect_2);
		// ▲▼ 基準だと右端ゲーム列(Ysオリジン/アーク/三国志2/終了)が欠ける。
		// 左ペインの右端コントロールを拾って幅を決める。
		auto widen = [&](UINT id) {
			if (CWnd* w = GetDlgItem(id)) {
				if (!::IsWindow(w->GetSafeHwnd())) return;
				CRect r;
				w->GetWindowRect(&r);
				if (r.right > rect_2.right) rect_2.right = r.right;
				if (r.bottom > rect_2.bottom) rect_2.bottom = r.bottom;
			}
		};
		widen(IDC_SLIDER2);      // シークバー(左ペイン幅の基準)
		widen(IDC_BUTTON15);     // Ys オリジン
		widen(IDC_BUTTON5);      // フェードアウト
		widen(IDOK);             // 終了
		widen(IDC_BUTTON51);     // アーク
		widen(IDC_BUTTON54);     // 三国志2
		widen(IDC_OGG_SWITCHMODE);
		rect_1.bottom = rect_2.bottom + kBottomPad;
		rect_1.right = rect_2.right + kRightPad;
		MoveWindow(&rect_1);
		if (maini)
			maini->MoveWindow(&rect_1);
	}
	else {
		m_ue.SetWindowText(_T("▼"));
		if (CWnd* g = GetDlgItem(IDC_OGG_GRP_MULTI))
			g->ShowWindow(SW_SHOW);
		if (CWnd* g = GetDlgItem(IDC_OGG_GRP_GAME))
			g->ShowWindow(SW_SHOW);
#if CCUSTOM_AERO_SUPPORT
		CCC_GroupBoxesBack(m_hWnd);
#endif
		CRect rect_1, rect_2;
		GetWindowRect(&rect_1);
		m_sita.GetWindowRect(&rect_2);
		rect_1.bottom = rect_2.bottom + kBottomPad;
		rect_1.right = rect_2.right + kRightPad;
		MoveWindow(&rect_1);
		if (maini)
			maini->MoveWindow(&rect_1);
	}
}

