static inline int Ms2FrameUnits()
{
	int ms = savedata.ms2;
	if (ms < 16) ms = 16;
	if (ms > 960) ms = 960;
	return (ms + 15) / 16;
}

static inline BOOL Ms2DrawDue(int frameCounter)
{
	return frameCounter >= Ms2FrameUnits();
}

