BOOL playwavBuffwav(BYTE* bw, int old, int l1, int l2)
{
	//	playb+=(l1+l2)/4;
	int rrr = readBuffwav((char*)bw + old, l1);
	if (l1 != rrr) {
		if (endf == 1) {
			// 途中の短読みは終端にしない（ゲーム音源でも RB/デコード端数がある）
			if (rrr < l1)
				ZeroMemory((char*)bw + old + rrr, (SIZE_T)(l1 - rrr));
			l1 = rrr;
			if (PlaybackShortMeansEof(rrr)) {
				if (savedata.saverenzoku == 0)
					fade1 = 1;
				else
					endflg = 1;
			}
		}
		else {
			// 壊れた loop 点で 0 バイト→seek(loop1)→また 0 の永久回りを止める
			// （曲長を超えた loop1 / 長さ0 / 誤読の loop1==loop2）
			if (rrr == 0 && (loop2 <= 0 || loop1 == loop2
				|| (data_size > 0 && (__int64)loop1 * PcmOutBytesPerFrame() >= (__int64)data_size))) {
				endf = 1;
				if (savedata.saverenzoku == 0) fade1 = 1; else endflg = 1;
				return FALSE;
			}
			PlaybackNoteLoop(loop1);
			poss = 0; poss2 = 0; poss3 = 0; poss4 = 0; poss6 = 0;
			seekadpcm(loop1);
			RubberBand_DestroyBank(0);
			reset = TRUE;
			int r2 = readBuffwav((char*)bw + old + rrr, (int)l1 - rrr);
			if (r2 <= 0 && rrr == 0) {
				endf = 1;
				if (savedata.saverenzoku == 0) fade1 = 1; else endflg = 1;
			}
		}
	}
	if (l2) {
		rrr = readBuffwav((char*)bw, l2);
		if (l2 != rrr) {
			if (endf == 1) {
				if (rrr < l2)
					ZeroMemory((char*)bw + rrr, (SIZE_T)(l2 - rrr));
				l2 = rrr;
				if (PlaybackShortMeansEof(rrr)) {
					if (savedata.saverenzoku == 0)
						fade1 = 1;
					else
						endflg = 1;
				}
			}
			else {
				if (rrr == 0 && (loop2 <= 0 || loop1 == loop2
					|| (data_size > 0 && (__int64)loop1 * PcmOutBytesPerFrame() >= (__int64)data_size))) {
					endf = 1;
					if (savedata.saverenzoku == 0) fade1 = 1; else endflg = 1;
					return FALSE;
				}
				PlaybackNoteLoop(loop1);
				poss = 0; poss2 = 0; poss3 = 0; poss4 = 0; poss6 = 0;
				seekadpcm(loop1);
				RubberBand_DestroyBank(0);
				reset = TRUE;
				int r2 = readBuffwav((char*)bw + rrr, (int)l2 - rrr);
				if (r2 <= 0 && rrr == 0) {
					endf = 1;
					if (savedata.saverenzoku == 0) fade1 = 1; else endflg = 1;
				}
			}
		}
	}
	return FALSE;
}

std::vector<uint8_t> outputRawBytesData;
// スライダー内部値 0..400（中央 200 = 再生 100%）。
// 表示用パーセントへ写す（旧 MP の GetPos()/2 とは別。400→300% が仕様）。
float TempoPercentFromPos(int tempoPos)
{
	float te = (float)tempoPos;
	if (te >= 200.0f)
		te -= 100.0f;
	else
		te = te / 3.0f + 33.3f;
	if (te < 5.0f) te = 5.0f;
	if (te > 800.0f) te = 800.0f;
	return te;
}

// RubberBand setTimeRatio 用（stretched/unstretched duration）。
// 表示 200% → 0.5 → 再生は 2 倍速。tempoRate2 も必ずこちら。
float TempoTimeRatioFromPos(int tempoPos)
{
	return 100.0f / TempoPercentFromPos(tempoPos);
}

// 壁時計換算の再生倍率。表示 200% → 2.0
double TempoPlaybackRateFromPos(int tempoPos)
{
	double r = (double)TempoPercentFromPos(tempoPos) / 100.0;
	if (r < 0.05) r = 0.05;
	if (r > 8.0) r = 8.0;
	return r;
}

// setPitchScale 用（1.0=原音）。テンポと同じ % マップ。
float PitchScaleFromPos(int pitchPos)
{
	return TempoPercentFromPos(pitchPos) / 100.0f;
}

// TempoPercentFromPos の逆写像（表示% → スライダー位置）
int TempoPosFromPercent(float percent)
{
	if (percent < 5.0f) percent = 5.0f;
	if (percent > 800.0f) percent = 800.0f;
	int pos;
	if (percent >= 100.0f)
		pos = (int)(percent + 100.0f + 0.5f);
	else
		pos = (int)((percent - 33.3f) * 3.0f + 0.5f);
	if (pos < 0) pos = 0;
	if (pos > 400) pos = 400;
	return pos;
}

// ---------------------------------------------------------------------------
// テンポ可変の壁時計予測（区間履歴は累積変数のみ。vector 不要）
//   経過 = 実壁時計（一時停止を除く）
//   総時間 = 経過 + 残りソース秒 / 現在レート
// 途中で 100%→300% に変えると、既に進んだ分は 100% のまま残り、残りだけ 300% で再計算される。
// ---------------------------------------------------------------------------
static void TempoPredReset(double srcSec, double wallSec, double rate)
{
	if (rate < 0.05) rate = 0.05;
	g_tpSrcSec = (srcSec > 0.0) ? srcSec : 0.0;
	g_tpLastWallSec = (wallSec > 0.0) ? wallSec : 0.0;
	g_tpWallAccSec = g_tpLastWallSec;
	g_tpLastRate = rate;
	g_tpWallTick0 = timeGetTime();
	g_tpWallRunning = 1;
}

// ループ頭へ：蓄積破棄。表示は loop1 の現在レート換算位置へ。
static void TempoPredOnLoopTo(int samplePos, double rate)
{
	if (rate < 0.05) rate = 0.05;
	double srcSec = 0.0;
	if (samplePos > 0 && wavbit_sample_Hz > 0)
		srcSec = (double)samplePos / (double)wavbit_sample_Hz;
	const double wallAt = srcSec / rate;
	TempoPredReset(srcSec, wallAt, rate);
}

// 再生スレッド（DispatchPlaywavFill→playwav*）から呼ぶ。UI の timerp でリセットする。
static void TempoPredNotifyLoop(int samplePos)
{
	InterlockedExchange(&g_tpLoopToSample, (LONG)samplePos);
	InterlockedExchange(&g_tpLoopPending, 1);
}

// ループ共通: カウンタ＋playb＋ソース位置＋予測時計通知（DispatchPlaywavFill 全形式）
static void PlaybackNoteLoop(int toSample)
{
	loopcnt++;
	playb = (__int64)toSample;
	poss5 = toSample; // ソースPCMサンプル位置に統一（旧 Buffwav のバイト計と混同しない）
	TempoPredNotifyLoop(toSample);
}

// 出力フレーム分だけ playb を進め、ソース相当の poss5 もテンポで進める
static void AdvanceOutAndSrcPos(int outSamples)
{
	if (outSamples <= 0) return;
	playb += outSamples;
	poss5 += (int)((double)outSamples * (double)TempoPlaybackRateFromPos(tempo) + 0.5);
}

// ループ再生ON、またはゲームループ(endf==0)のとき true
static bool WantPlaybackLoop()
{
	return (savedata.saveloop != 0) || (endf == 0);
}

// ソース総PCMサンプル数（loop点 / loop3保存総長 / oggsize）。不明は 0。
static int PlaybackSrcTotalSamples()
{
	if (loop2 > 0)
		return loop1 + loop2;
	if (loop3 > 0)
		return loop3;
	const int dm = ActiveDecodeMode();
	// MP3: oggsize / playb は PCM フレーム数
	if (dm == -10 && oggsize > 0)
		return oggsize;
	if (oggsize > 0 && wavchannel > 0 && wavsam_depth >= 8) {
		const int bps = wavsam_depth / 8;
		if (bps > 0)
			return oggsize / (wavchannel * bps);
	}
	return 0;
}

// 短読みを曲終端にしてよいか。途中の RB待ち・デコード端数では false（誤停止防止）。
// gotBytes<=0 は真の欠落/EOF。総長が信頼できるときだけ位置で判定（DSD/MP3既存方針と揃える）。
// KPI(mode==-3): dwLength/loop3 は UI 目安で実デコードより短いことが多い（OPI/FM 等）。
// 位置比較で止めると表示長ちょうどでプツリ切れになるので、ゼロ返却だけを EOF にする。
static bool PlaybackShortMeansEof(int gotBytes)
{
	if (gotBytes <= 0)
		return true;
	const int dm = ActiveDecodeMode();
	// KPI / 外部プラグイン / mid VST: 途中短読みは誤停止しやすい。
	// ゼロ返却と無音連続（playwav* 側）で止める。
	if (dm == -3 || IsForeignPluginMode(dm) || dm == MODE_VST_MIDI)
		return false;
	const int total = PlaybackSrcTotalSamples();
	const int hz = (wavbit_sample_Hz > 0) ? wavbit_sample_Hz : 44100;
	if (total < hz)
		return false;
	const int margin = hz / 2; // ~0.5s
	const int pos = (poss5 > 0) ? poss5 : (int)playb;
	return (pos + margin >= total);
}

// 予測用ソースは壁時計積分のみ（poss5/decode を毎フレ入れると総時間がゆれる）。
// 実デコード位置はシーク棒用。大きく乖離したときだけ補正。
ULONGLONG g_seekUiHoldUntil = 0; // シーク直後、旧 decode 位置で棒が戻るのを抑止 / xfade 抑止
/* ジャケ差し替え直後: rem overlay Invalidate を抑止 */
ULONGLONG g_xfJacketStableUntil = 0;
static int TempoPredRealSrcSamples()
{
	// シーク確定直後は playb/poss5 を優先（g_oggPcmDecodePos が1フレ遅れると棒が跳ねる）
	if (g_seekUiHoldUntil != 0 && GetTickCount64() < g_seekUiHoldUntil) {
		if (poss5 > 0) return poss5;
	}
	const int dm = ActiveDecodeMode();
	if (dm == -1 && g_oggPcmDecodePos >= 0)
		return (int)g_oggPcmDecodePos;
	if (poss5 > 0)
		return poss5;
	return -1;
}

static void TempoPredSyncSourcePos(double wallSec, double rateNow, double totalSrcSec)
{
	if (rateNow < 0.05) rateNow = 0.05;
	TempoPredAdvanceTo(wallSec, rateNow, totalSrcSec);

	// DSバッファ単位の poss5 と連続時計の差が 1 秒超えたときだけ合わせる（ゆれ防止）
	if (wavbit_sample_Hz > 0) {
		const int realSamp = TempoPredRealSrcSamples();
		if (realSamp >= 0) {
			const double realSec = (double)realSamp / (double)wavbit_sample_Hz;
			if (fabs(realSec - g_tpSrcSec) > 1.0) {
				g_tpSrcSec = realSec;
				if (g_tpSrcSec > totalSrcSec) g_tpSrcSec = totalSrcSec;
				if (g_tpSrcSec < 0.0) g_tpSrcSec = 0.0;
			}
		}
	}
}

static void TempoPredStopClock()
{
	if (!g_tpWallRunning) return;
	const DWORD now = timeGetTime();
	g_tpWallAccSec += (double)(now - g_tpWallTick0) * 0.001;
	if (g_tpWallAccSec < 0.0) g_tpWallAccSec = 0.0;
	g_tpWallRunning = 0;
}

static void TempoPredResumeClock()
{
	if (g_tpWallRunning) return;
	g_tpWallTick0 = timeGetTime();
	g_tpWallRunning = 1;
}

static double TempoPredWallNow()
{
	if (!g_tpWallRunning)
		return g_tpWallAccSec;
	const DWORD now = timeGetTime();
	double w = g_tpWallAccSec + (double)(now - g_tpWallTick0) * 0.001;
	if (w < 0.0) w = 0.0;
	return w;
}

// wall が進んだ分を「その時点のレート」でソース消費に足す。レート変更は次回Δから新レート。
static void TempoPredAdvanceTo(double wallSec, double rateNow, double totalSrcSec)
{
	if (rateNow < 0.05) rateNow = 0.05;
	if (totalSrcSec < 0.0) totalSrcSec = 0.0;

	double dWall = wallSec - g_tpLastWallSec;
	if (dWall < -0.05) {
		// 呼び出し側で Reset 済みの想定。ここでは時計だけ合わせる
		g_tpLastWallSec = wallSec;
		g_tpLastRate = rateNow;
		return;
	}
	if (dWall > 0.0) {
		g_tpSrcSec += dWall * g_tpLastRate;
		if (g_tpSrcSec > totalSrcSec) g_tpSrcSec = totalSrcSec;
		if (g_tpSrcSec < 0.0) g_tpSrcSec = 0.0;
	}
	g_tpLastWallSec = wallSec;
	g_tpLastRate = rateNow;
}

// ループ／シークでソース位置が分かっているとき
static void TempoPredSetSourceSec(double srcSec, double wallSec, double rateNow)
{
	if (rateNow < 0.05) rateNow = 0.05;
	g_tpSrcSec = (srcSec > 0.0) ? srcSec : 0.0;
	g_tpLastWallSec = wallSec;
	g_tpLastRate = rateNow;
}

int readtempo(BYTE* data, int len,bool t = false)
{
	// テンポ/ピッチが両方 100%(スライダ 200)のときは RubberBand を通さない。
	// 常時 float 往復+RB が再生スレッドを食いつぶし、ピアノロール/アナライザが
	// 体感で数倍重くなる主因だった。伸縮が必要なときだけ RB を使う。
	const bool doFinalFlush = t || (len <= 0);
	const bool identity = (tempo == 200 && pitch == 200);
	static bool s_rbBypassActive = true;

	if (identity) {
		if (!s_rbBypassActive) {
			// 伸縮→100% 復帰: 内部バッファを破棄してから素通しへ
			RubberBand_DestroyBank(0);
			s_rbBypassActive = true;
		}
		m_convertedPcmFloatData.clear();
		if (doFinalFlush || len <= 0) {
			outputRawBytesData.clear();
			return 0;
		}
		if (!data) {
			outputRawBytesData.clear();
			return 0;
		}
		outputRawBytesData.resize((size_t)len);
		memcpy(outputRawBytesData.data(), data, (size_t)len);
		return len;
	}

	s_rbBypassActive = false;
	m_bufwav3_1.clear();
	if (len > 0) {
		m_bufwav3_1.resize(len);
		memcpy(m_bufwav3_1.data(), (data), len);
	}
	const float te = TempoTimeRatioFromPos(tempo);
	// len<=0 のときは常に final 相当で吐き出す（fade1 中も同様）。
	// fade1 中だけ flush しないと RB 内部にサンプルが残り、無音フェードとぶつかって「ボコ」と消える。
	// g_rubberBandFinalFlushed で2回目以降は空返しなので無限ループにならない。
	if (!ProcessAudioWithRubberBand(te, doFinalFlush)) {
		// 空入力で process されなかったとき、前回の m_converted を再エンコードすると
		// 同じフレームがもう一度出力され末尾が「たぶる」（二重になる）
		m_convertedPcmFloatData.clear();
		outputRawBytesData.clear();
		return 0;
	}
//	ProcessAudioWithSoundTouch(te,t);
	int bits;
	// 再生スレッドから呼ばれる。mode は次曲に差し替わっていることがある
	if (ActiveDecodeMode() == -10) {
		bits = Mp3DecoderBitsClampedFromObject();
	}
	else {
		bits = (wavsam_depth <= 0 || wavsam_depth > 32) ? 16 : abs(wavsam_depth);
		if (!(bits == 8 || bits == 16 || bits == 24 || bits == 32)) bits = 16;
	}
	uint16_t outBps = (uint16_t)bits;
	ConvertFloatToRawBytes(m_convertedPcmFloatData, outBps, wavchannel, outputRawBytesData);
	return outputRawBytesData.size();
}
using namespace std;
void equaliser(void* data, int len, BOOL reset = FALSE);
void EqualiserSetFormatVolContext(int mode, BOOL spcApplicable);
int readBuffwav(char* bw, int cnt)
{
	EqualiserSetFormatVolContext(0, FALSE);
	int r = cnt, rr = cnt;
	int cnt2;
	if (rr == 0)return 0;

	int max_buffer_size = OUTPUT_BUFFER_SIZE * OUTPUT_BUFFER_NUM * 3;
	if (poss4 <= cnt) {
		int buffRbStallIters = 0;
		const int kBuffRbStallMax = 512;
		while (true) {
			if (IsPlaybackStopRequested())
				return 0;
			int f = 0;
			if (adbuf2 == NULL) return 0;
			// fade は ApplyFadeCubed で音量(例: 1.0=フル)。ここでは「無音に近い」ときだけゼロ埋め+muon。
			// fade==0 判定だと play() 開始時の fade=1.0 で常に else になり、無音のまま lenl だけ進んで即終了する。
			if (fade > 0.0001f)
				memcpy((void*)bufkpi, (void*)(adbuf2 + lenl), cnt);
			else
			{
				ZeroMemory(bufkpi, cnt);
				muon--;
			}

			if (playb > (data_size + 100000) / PcmOutBytesPerFrame() && muon != 0) {
				rrr = 0;
			}
			if (muon <= 0) {
				endf = 1;
				return 0;
			}

			int len2 = readtempo(bufkpi, cnt);
			lenl += cnt;

			if (len2 > 0) {
				buffRbStallIters = 0;
				// 書き込み
				RingBufWrite(bufkpi3, max_buffer_size, poss2, outputRawBytesData.data(), len2);
				poss4 += len2;
			}
			// playb はリングから bw へ渡したバイト数で進める（len2 積み上げは cnt を超え表示が実長より長くなる）
			if (poss4 > cnt) break;
			if (len2 <= 0 && fade1 == 1) break;
			if (len2 <= 0) {
				if (++buffRbStallIters >= kBuffRbStallMax)
					break;
			}
		}
	}

	int cnt0 = cnt;
	{
		const int bpfLoop = PcmOutBytesPerFrame();
		// poss5 はソースPCMサンプル。loopEnd もサンプルで比較する。
		int loopEndSamples = 0;
		if (loop1 == 0 && loop2 == 0) {
			loopEndSamples = (bpfLoop > 0) ? (int)((__int64)data_size / bpfLoop) : 0;
		}
		else if (loop2 > 0 && loop1 != loop2) {
			loopEndSamples = loop1 + loop2;
		}
		else if (loop1 != 0 && loop1 == loop2) {
			loopEndSamples = (bpfLoop > 0) ? (int)((__int64)data_size / bpfLoop) : 0;
		}
		const int outSamples = (bpfLoop > 0) ? (cnt0 / bpfLoop) : 0;
		if (loopEndSamples > 0 && endf == 0 && poss5 + outSamples > loopEndSamples) {
			cnt0 = (loopEndSamples - poss5) * bpfLoop;
			if (cnt0 < 0)
				cnt0 = 0;
		}
	}
	cnt2 = cnt0;

	if (cnt2 > 0) {
		RingBufRead(bw, bufkpi3, max_buffer_size, poss3, cnt0);
		poss4 -= cnt0;
		{
			const int bpf = PcmOutBytesPerFrame();
			if (bpf > 0 && cnt0 > 0)
				playb += cnt0 / bpf;
		}
	}

	equaliser(bw, cnt2, reset);
	og->FeedPianoRoll(bw, cnt2);
	reset = FALSE;

	fade += fadeadd;
	if (fade < 0.0001f) { fade = 0.0f; fadeadd = 0.0f; }
	ApplyFadeCubedToInterleavedPcm(bw, cnt2);

	wl += PlaybackCcWrite(bw, cnt0);

	{
		const int bpf = PcmOutBytesPerFrame();
		if (bpf > 0 && cnt0 > 0)
			poss5 += (int)((double)(cnt0 / bpf) * TempoPlaybackRateFromPos(tempo) + 0.5);
	}

	return cnt0;
}

int seekadpcm(int pos)
{
	ResetAudioUpscalerPipeline();
	const int bpf = PcmOutBytesPerFrame();
	lenl = pos * bpf;
	playb = pos;
	// poss5 はソースPCMサンプル位置（PlaybackNoteLoop / readBuffwav と同じ単位）。
	// 旧バイト計 (lenl) のままだとループ終端判定が壊れシークも loop1 に吸い寄せられる。
	poss5 = pos;
	poss = 0;
	poss2 = poss3 = poss4 = poss6 = 0;
	RubberBand_DestroyBank(0);
	return 0;
}

static inline short  R16(const unsigned char* src)
{
	return (short)((unsigned short)src[0] | ((unsigned short)src[1] << 8));
}

static inline void  W16(unsigned char* dst, short s)
{
	dst[0] = LOBYTE(s);
	dst[1] = HIBYTE(s);
}

static inline void clamp_sample(int* sample)
{
	if (*sample < -32768) *sample = -32768;
	if (*sample > 32767) *sample = 32767;
}

static inline void process_nibble(unsigned nibble, int* idelta,
	int* sample1, int* sample2,
	const ADPCMCOEFSET* coeff)
{
	int sample;
	int snibble;

	/* nibble is in fact a signed 4 bit integer => propagate sign if needed */
	snibble = (nibble & 0x08) ? (nibble - 16) : nibble;
	sample = ((*sample1 * coeff->iCoef1) + (*sample2 * coeff->iCoef2)) / 256 +
		snibble * *idelta;
	clamp_sample(&sample);

	*sample2 = *sample1;
	*sample1 = sample;
	*idelta = ((MS_Delta[nibble] * *idelta) / 256);
	if (*idelta < 16) *idelta = 16;
}

unsigned char* bbuf1;
unsigned char* bw2;

int readadpcm(CFile& adpcmf, char* bw, int len)
{
	int c = 0;
	adpcmf.SeekToBegin();
	adpcmf.Read(bbuf, 0x2c);
	int cnt = 2048;
	int ak = 0, lbuf = 0;
	bw2 = (unsigned char*)bw;
	for (;;) {
		if (IsPlaybackStopRequested())
			return 0;
		if (lbuf == 0) {
			adpcmf.Read(abuf, 0x8);
			lbuf = 0x5000;
		}

		if (ak == 0) {
			cnt = adpcmf.Read(bbuf, 2048);
			if (cnt == 0) {
				wavwait = 1;
				return 0;
			}
			bbuf1 = (unsigned char*)bbuf;
			coeffL = MSADPCM_CoeffSet[*bbuf1++];
			coeffR = MSADPCM_CoeffSet[*bbuf1++];
			ideltaL = R16(bbuf1);    bbuf1 += 2;
			ideltaR = R16(bbuf1);    bbuf1 += 2;
			sample1L = R16(bbuf1);    bbuf1 += 2;
			sample1R = R16(bbuf1);    bbuf1 += 2;
			sample2L = R16(bbuf1);    bbuf1 += 2;
			sample2R = R16(bbuf1);    bbuf1 += 2;
			W16(bw2, sample2L);      bw2 += 2;
			W16(bw2, sample2R);      bw2 += 2;
			W16(bw2, sample1L);      bw2 += 2;
			W16(bw2, sample1R);      bw2 += 2;
			lbuf -= 14;
		}
		for (int k = ak; k < (cnt - 14); k++) {
			process_nibble(*bbuf1 >> 4, &ideltaL, &sample1L, &sample2L, &coeffL);
			W16(bw2, sample1L);	bw2 += 2;
			process_nibble(*bbuf1++ & 0x0F, &ideltaR, &sample1R, &sample2R, &coeffR);
			W16(bw2, sample1R);	bw2 += 2;	lbuf--;
			c += 4; if (c >= (int)(WAVDALen / OUTPUT_BUFFER_NUM) * 8)	wavwait = 1;
			if (thend1 == TRUE) return 1;
		}
		ak = 0;
	}
}

static BOOL decode_msadpcm_wav(CFile& f, const wavinfo& wi, char** outBuf, int* outSize)
{
	int nCh = (int)wi.nChannels;
	int blockAlign = wi.nBlockAlign > 0 ? (int)wi.nBlockAlign : 256;
	int samplesPerBlock = wi.nSamplesPerBlock > 0 ? (int)wi.nSamplesPerBlock : 256;
	__int64 dataSize = wi.dataSize;
	int preambleSize = 7 * nCh;
	if (blockAlign <= preambleSize) return FALSE;
	int blocks = (int)(dataSize / blockAlign);
	int totalSamples = blocks * samplesPerBlock;
	int outBytes = totalSamples * 2 * nCh;
	char* buf = (char*)calloc((size_t)outBytes + 4096, 1);
	if (!buf) return FALSE;
	unsigned char* dst = (unsigned char*)buf;
	BYTE blockBuf[512];
	f.Seek((LONG)wi.dataOffset, CFile::begin);
	for (int blk = 0; blk < blocks && !thend1; blk++) {
		if (f.Read(blockBuf, blockAlign) != (UINT)blockAlign) break;
		unsigned char* p = blockBuf;
		int ideltaL, ideltaR, s1L, s2L, s1R, s2R;
		ADPCMCOEFSET coeffL, coeffR;
		coeffL = MSADPCM_CoeffSet[p[0]]; coeffR = (nCh >= 2) ? MSADPCM_CoeffSet[p[1]] : coeffL;
		p += nCh;
		ideltaL = (short)(p[0] | (p[1] << 8)); p += 2;
		ideltaR = (nCh >= 2) ? (short)(p[0] | (p[1] << 8)) : ideltaL; p += (nCh >= 2) ? 2 : 0;
		s1L = (short)(p[0] | (p[1] << 8)); p += 2;
		s1R = (nCh >= 2) ? (short)(p[0] | (p[1] << 8)) : s1L; p += (nCh >= 2) ? 2 : 0;
		s2L = (short)(p[0] | (p[1] << 8)); p += 2;
		s2R = (nCh >= 2) ? (short)(p[0] | (p[1] << 8)) : s2L; p += (nCh >= 2) ? 2 : 0;
		W16(dst, s2L); dst += 2;
		if (nCh >= 2) { W16(dst, s2R); dst += 2; }
		W16(dst, s1L); dst += 2;
		if (nCh >= 2) { W16(dst, s1R); dst += 2; }
		int dataBytes = blockAlign - preambleSize;
		for (int i = 0; i < dataBytes; i++) {
			unsigned char b = p[i];
			if (nCh >= 2) {
				process_nibble(b >> 4, &ideltaL, &s1L, &s2L, &coeffL);
				W16(dst, s1L); dst += 2;
				process_nibble(b & 0x0F, &ideltaR, &s1R, &s2R, &coeffR);
				W16(dst, s1R); dst += 2;
			}
			else {
				process_nibble(b >> 4, &ideltaL, &s1L, &s2L, &coeffL);
				W16(dst, s1L); dst += 2;
				process_nibble(b & 0x0F, &ideltaL, &s1L, &s2L, &coeffL);
				W16(dst, s1L); dst += 2;
			}
		}
	}
	*outBuf = buf;
	*outSize = (int)(dst - (unsigned char*)buf);
	return TRUE;
}

int readadpcmzwei(CFile& adpcmf, char* bw, int len)
{
	adpcmf.Read(bbuf, 0x2c);
	//	adpcmf.Read(bbuf,0x800);
	//	adpcmf.Read(abuf,0x8);
	int c = 0;
	int cnt = 2048;
	int ak = 0, lbuf = 0, o = 0;
	bw2 = (unsigned char*)bw;
	for (;;) {
		if (IsPlaybackStopRequested())
			return 0;
		if (lbuf == 0) {
			adpcmf.Read(abuf, 0x8);
			lbuf = 0x5000;
		}
		if (ak == 0) {
			cnt = adpcmf.Read(bbuf, 2048);
			if (cnt == 0)
				return 0;
			bbuf1 = (unsigned char*)bbuf;
			coeffL = MSADPCM_CoeffSet[*bbuf1++];
			coeffR = MSADPCM_CoeffSet[*bbuf1++];
			ideltaL = R16(bbuf1);    bbuf1 += 2;
			ideltaR = R16(bbuf1);    bbuf1 += 2;
			sample1L = R16(bbuf1);    bbuf1 += 2;
			sample1R = R16(bbuf1);    bbuf1 += 2;
			sample2L = R16(bbuf1);    bbuf1 += 2;
			sample2R = R16(bbuf1);    bbuf1 += 2;
			W16(bw2, sample2L);      bw2 += 2;
			W16(bw2, sample2R);      bw2 += 2;
			W16(bw2, sample1L);      bw2 += 2;
			W16(bw2, sample1R);      bw2 += 2;
			len -= 14; lbuf -= 14;
		}
		for (int k = ak; k < (cnt - 14); k++) {
			process_nibble(*bbuf1 >> 4, &ideltaL, &sample1L, &sample2L, &coeffL);
			if (o == 0) {
				W16(bw2, 0);	bw2 += 2;
			}
			else {
				W16(bw2, sample1L);	bw2 += 2;
			}
			process_nibble(*bbuf1++ & 0x0F, &ideltaR, &sample1R, &sample2R, &coeffR);
			if (o == 0) {
				W16(bw2, 0);	bw2 += 2;
			}
			else {
				W16(bw2, sample1R);	bw2 += 2;
			}
			len--; lbuf--;
			c += 4; if (c >= (int)(WAVDALen / OUTPUT_BUFFER_NUM) * 8)	wavwait = 1;
			if (len <= 0) return 0;
			if (thend1 == TRUE) return 1;
		}
		ak = 0;
		o = 1;
	}
}

