// stop() で保存した playb を再生開始時にデコーダへ反映(OnHScroll と同系統)
static bool IsMidiLikePath(const CString& path)
{
	if (path.IsEmpty()) return false;
	CString e = path;
	const int d = e.ReverseFind(_T('.'));
	if (d < 0) return false;
	e = e.Mid(d);
	e.MakeLower();
	return e == _T(".mid") || e == _T(".midi") || e == _T(".kar") || e == _T(".rmi");
}

// MIDI KPI: Seek だけでは音色/CC/ノートが復元されない。先頭→目標まで Render 破棄。
// MIDI シークは高速レンダで長くかかり、その間 DS リングが回り続けると古い音がループする。
// シーク中は Stop + リング全消しし、終わったら再生中だった場合だけ再開する。
struct MidiSeekDsGuard {
	BOOL active;
	BOOL wasPlaying;
	MidiSeekDsGuard()
		: active(FALSE), wasPlaying(FALSE)
	{
		extern IAudioClient* pAudioClient;
		extern ULONG g_ds_buffer_bytes;
		extern int ps;
		extern BOOL thn;
		extern LPDIRECTSOUNDBUFFER8 m_dsb;
		if (!m_dsb) return;
		active = TRUE;
		DWORD st = 0;
		if (m_dsb->GetStatus(&st) == DS_OK && (st & DSBSTATUS_PLAYING))
			wasPlaying = TRUE;
		m_dsb->SetVolume(DSBVOLUME_MIN);
		m_dsb->Stop();
		if (pAudioClient)
			pAudioClient->Stop();
		const ULONG ring = (g_ds_buffer_bytes > 0) ? g_ds_buffer_bytes
			: (ULONG)(OUTPUT_BUFFER_SIZE * OUTPUT_BUFFER_NUM);
		LPVOID p1 = NULL, p2 = NULL;
		DWORD l1 = 0, l2 = 0;
		if (ring > 0 && m_dsb->Lock(0, ring, &p1, &l1, &p2, &l2, 0) == DS_OK) {
			if (p1 && l1) ZeroMemory(p1, l1);
			if (p2 && l2) ZeroMemory(p2, l2);
			m_dsb->Unlock(p1, l1, p2, l2);
		}
		(void)ps;
		(void)thn;
	}
	~MidiSeekDsGuard()
	{
		extern IAudioClient* pAudioClient;
		extern int ps;
		extern BOOL thn;
		extern LPDIRECTSOUNDBUFFER8 m_dsb;
		if (!active || !m_dsb) return;
		LONG vol = (LONG)(savedata.dsvol - 1) * 10;
		if (vol < DSBVOLUME_MIN) vol = DSBVOLUME_MIN;
		if (vol > DSBVOLUME_MAX) vol = DSBVOLUME_MAX;
		m_dsb->SetVolume(vol);
		// ユーザー一時停止中は再開しない
		if (wasPlaying && ps == 0 && thn == FALSE) {
			m_dsb->Play(0, 0, DSBPLAY_LOOPING);
			if (pAudioClient)
				pAudioClient->Start();
		}
	}
};

static void KpiMidiSeekAccurate(__int64 samplePos)
{
	MidiSeekDsGuard dsHold;
	if (samplePos < 0) samplePos = 0;
	kpi_silence_bytes = 0;
	const int ch = (wavchannel > 0) ? wavchannel : 2;
	const int srcBits = wavsam_src;
	const int outBits = abs(wavsam_depth) > 0 ? abs(wavsam_depth) : 16;
	const DWORD chunk = 8192;

	if (g_kpiRemote && g_kpiSession.sessionId != 0) {
		// KpiHost64 側 Cmd_Seek が MIDI なら Render 破棄する
		uint64_t np = 0;
		g_kpiHost.Seek(g_kpiSession.sessionId, (uint64_t)samplePos, KPI_MEDIAINFO::SEEK_FLAGS_SAMPLE, np);
		ResetKpiRemoteCache();
		return;
	}

	if (kvver == 5 && kpidec) {
		kpidec->Seek(0, KPI_MEDIAINFO::SEEK_FLAGS_SAMPLE);
		__int64 left = samplePos;
		std::vector<BYTE> junk;
		while (left > 0) {
			DWORD ask = (DWORD)((left > (__int64)chunk) ? chunk : left);
			if (srcBits == -32)
				junk.resize((size_t)ask * (size_t)ch * sizeof(float));
			else if (srcBits == -64)
				junk.resize((size_t)ask * (size_t)ch * sizeof(double));
			else
				junk.resize((size_t)ask * (size_t)ch * (size_t)(outBits / 8));
			DWORD got = kpidec->Render(junk.data(), ask);
			if (got == 0) break;
			if ((__int64)got > left) got = (DWORD)left;
			left -= got;
		}
		return;
	}

	if (kvver == 2 && og && og->mod && og->mod->SetPosition && og->mod->Render) {
		HKMP hk = og->kmp1;
		if (!hk) return;
		og->mod->SetPosition(hk, 0);
		const int bpf = (outBits / 8) * ch;
		if (bpf <= 0) return;
		__int64 leftBytes = samplePos * bpf;
		std::vector<BYTE> junk((size_t)chunk * (size_t)bpf);
		while (leftBytes > 0) {
			DWORD ask = (DWORD)((leftBytes > (__int64)junk.size()) ? junk.size() : leftBytes);
			DWORD got = og->mod->Render(hk, junk.data(), ask);
			if (got == 0) break;
			if ((__int64)got > leftBytes) got = (DWORD)leftBytes;
			leftBytes -= got;
		}
	}
}

static void KpiSeekToPlayb(__int64 samplePos)
{
	kpi_silence_bytes = 0;
	const CString path = !filen.IsEmpty() ? filen : (og ? CString(og->kpi) : CString());
	if (IsMidiLikePath(path)) {
		KpiMidiSeekAccurate(samplePos);
		return;
	}
	if (g_kpiRemote && g_kpiSession.sessionId != 0) {
		uint64_t np = 0;
		g_kpiHost.Seek(g_kpiSession.sessionId, (uint64_t)samplePos, KPI_MEDIAINFO::SEEK_FLAGS_SAMPLE, np);
		ResetKpiRemoteCache();
		return;
	}
	if (kvver == 5 && kpidec) {
		kpidec->Seek((UINT64)samplePos, KPI_MEDIAINFO::SEEK_FLAGS_SAMPLE);
		return;
	}
	if (kvver == 2 && og && og->mod && og->mod->SetPosition) {
		HKMP hk = og->kmp1;
		if (hk && og->sikpi.dwSeekable)
			og->mod->SetPosition(hk, (DWORD)((double)samplePos / (((double)wavbit_sample_Hz * (double)wavchannel) / 2000.0)));
	}
}

static void VstSeekToPlayb(__int64 samplePos)
{
	MidiSeekDsGuard dsHold;
	kpi_silence_bytes = 0;
	if (VstRemoteNow()) {
		const int slot = VstBindIoSlot();
		VstPrefetchStop(slot);
		g_kpiHost.VstSeek((uint64_t)samplePos, (uint32_t)slot);
		VstPrefetchStart(slot, wavbit_sample_Hz, wavchannel, abs(wavsam_depth), 1);
	} else {
		VstMidiSeekSamples(samplePos);
	}
}

static void ResumeApplyPlaybSeek(__int64 pb)
{
	playb = pb;
	if (mode == -10) {
		if (oggsize > 0 && playb > (__int64)oggsize)
			playb /= 4;
		if (savedata.mp3orig)
			mp3_.seek2(Mp3SeekDwPosFromPlaybFrames(playb), wavchannel);
		else
			mp3_.seek(Mp3SeekDwPosFromPlaybFrames(playb), wavchannel);
		return;
	}
	if (mode == 999) {
		if (wav999_use_adbuf)
			seekadpcm((int)playb);
		else
			wav_.Seek(playb);
		return;
	}
	// mid VST / KPI は og 無し（リモート含む）でもシークできる
	if (mode == -3) {
		KpiSeekToPlayb(playb);
		return;
	}
	if (mode == MODE_VST_MIDI) {
		VstSeekToPlayb(playb);
		return;
	}
	if (!og) return;
	if (mode == -8) {
		if (og->kmp) {
			const double aa = 2000.0;
			if (flacmode == 1) flac_.SetPosition(og->kmp, playb);
			else flac_.SetPosition(og->kmp, (LONGLONG)((double)playb / (((double)wavbit_sample_Hz * (double)wavchannel) / aa)));
		}
		return;
	}
	if (mode == -9) {
		if (og->kmp) {
			double wavv2[] = { 0, 2.0, 1.0, 1.0 / 2.0, 1.0 / 2.0, 1.0 / 2.0, 1.0 / 2.0 };
			DWORD pla = (DWORD)((double)playb / (((double)(wavbit2 / wavv2[wavchannel])) / ((wavchannel > 2) ? (1069.1 * wavchannel) : 1000.0)));
			if (wavchannel > 0)
				pla = (pla / (wavchannel * 2) * (wavchannel * 2));
			m4a_.SetPosition(og->kmp, pla);
		}
		return;
	}
	if (mode == -7) {
		dsd_.kpiSetPosition(og->kmp, (DWORD)((double)playb / (((double)wavbit_sample_Hz * (double)wavchannel) / 2000.0)));
		return;
	}
	if (mode == MODE_PLUGIN_WINAMP) {
		if (wavbit_sample_Hz > 0)
			PluginWinamp_SeekMs((int)((playb * 1000) / wavbit_sample_Hz));
		return;
	}
	if (mode == MODE_PLUGIN_XMPLAY) {
		if (wavbit_sample_Hz > 0)
			PluginXmplay_SeekSec((double)playb / (double)wavbit_sample_Hz);
		return;
	}
	if (mode == MODE_PLUGIN_AIMP) {
		const int bpf = (wavsam_depth / 8) * wavchannel;
		if (bpf > 0)
			PluginAimp_SeekBytes((__int64)playb * bpf);
		return;
	}
	if (mode == -1) {
		SeekAndWarmupRubberBand((int)playb, false);
		return;
	}
	// opus / ゲームBGM / adbuf 系
	if (((mode >= 1 && mode <= 21) || IsBuffwavNegMode(mode) || mode == -6 || mode == 34 || mode == 35 || mode == 30) && mode != -10) {
		seekadpcm((int)playb);
		return;
	}
}

// 再生通知スレッドが動いている／動いていた可能性があるか（形式を問わず）
static inline bool PlaybackNotifyThreadMayBeActive()
{
	return plf != 0 || playf != 0 || ogg != NULL || adbuf2 != NULL || (og && og->mod != NULL)
		|| wav != NULL || mode == 999 || mode == -10 || mode == -9 || mode == -8
		|| mode == -7 || mode == -6 || mode == 34 || mode == 35 || mode == -3 || mode == -1 || mode == 30
		|| mode == MODE_PLUGIN_WINAMP || mode == MODE_PLUGIN_XMPLAY || mode == MODE_PLUGIN_AIMP
		|| mode == MODE_VST_MIDI
		|| (mode > 0 && mode <= 21);
}

void COggDlg::stop()
{
	// play/stop1 実行中の再入: 停止要求だけ出して本体は触らない
	if (s_inPlay || s_inStop1) {
		playf = 0;
		plf = 0;
		SignalPlaybackNotifyThreadStop();
		if (::IsWindow(m_PianoRollDlg->GetSafeHwnd()))
			m_PianoRollDlg->PauseAnalysis();
		if (::IsWindow(m_AnalyzerDlg->GetSafeHwnd()))
			m_AnalyzerDlg->PauseFeed();
		MpPromptOnPlaybackStop();
		return;
	}
	s_inStop1 = true;
	struct ClearInStop1 { ~ClearInStop1() { s_inStop1 = false; } } _clearInStop1;
	ResumePromptKillQueued();
	ResumeDrainQueuedKeyDowns();

	// DoEvent 再入より先に解析を止める（停止ボタンでは起きず曲切替で落ちる主因）
	playf = 0;
	plf = 0;
	if (::IsWindow(m_PianoRollDlg->GetSafeHwnd()))
		m_PianoRollDlg->PauseAnalysis();
	if (::IsWindow(m_AnalyzerDlg->GetSafeHwnd()))
		m_AnalyzerDlg->PauseFeed();

	if (PlaybackNotifyThreadMayBeActive())
		SignalPlaybackNotifyThreadStop();

	fade1 = 0;
	endflg = 0;
	TempoPredReset(0.0, 0.0, 1.0);
	TempoPredStopClock();
	g_tpLastLoopcnt = -1;
	g_tpUiValid = 0;
	InterlockedExchange(&g_tpLoopPending, 0);

	if (!img.IsNull()) {
		img.Destroy();
	}
	jx = -1;
	lrc_backup = L"";
	lrccur = 0;
	loop1_2 = -1;
	stflg = TRUE;
	KillTimer(1250);
	// filenback 一致条件は初回停止・曲替わり後の停止で保存が永遠にスキップされるため廃止。
	// 曲切替時は stop1() 側で保存しない（プレイリストTipの仕様どおり）。
	const BOOL wantResumeSave =
		(savedata.savecheck == 1 || savedata.savecheck_mp3 == 1 || savedata.savecheck_dshow == 1)
		&& (ResumeModeUsesPlayb(mode) || ResumeDshowApplies(mode, filen));
	if (wantResumeSave) {
		try {
			int flg = 0;
			if (ResumeModeUsesPlayb(mode)) {
				if (ResumePlaybAtEndOrStart()) {
					try {
						ResumeSaveRemove(filen);
					}
					catch (...) {
					}
					flg = 1;
				}
			}
			if (ResumeDshowApplies(mode, filen)) {
				if (oggsize2 <= aa1_ && oggsize2 != 0.0) {
					try {
						ResumeSaveRemove(filen);
					}
					catch (...) {
					}
					flg = 1;
				}
				if (aa1_ == 0.0) {
					flg = 1;
				}
			}
			if (flg == 0) {
				// savecheck_mp3: 内蔵音源全形式 / savecheck_dshow: 動画等（mid は除外）
				if ((savedata.savecheck_mp3 == 1 && ResumeModeUsesPlayb(mode)) || (savedata.savecheck_dshow == 1 && ResumeDshowApplies(mode, filen))) {
					CFile f;
					const CString savePath = ResumeSavePathNew(filen);
					if (!savePath.IsEmpty() && f.Open(savePath, CFile::modeCreate | CFile::modeWrite | CFile::shareExclusive, NULL) == TRUE) {
						if (ResumeModeUsesPlayb(mode))
							f.Write(&playb, sizeof(__int64));
						if (ResumeDshowApplies(mode, filen))
							f.Write(&aa1_, sizeof(double));
						f.Close();
						// 旧・メディア隣サイドカーは残さない
						ResumeSaveRemoveLegacyOnly(filen);
					}
				}
			}
		}
		catch (...) {
		}
	}
	filenback = filen;
	playb = 0;
	if (ptl)ptl->SetProgressValue(m_hWnd, (LONGLONG)0, (LONGLONG)1);
	if (ptl)ptl->SetProgressState(m_hWnd, TBPF_NOPROGRESS);
	if (PlaybackNotifyThreadMayBeActive())
	{
		SignalPlaybackNotifyThreadStop();
		if (m_dsb)m_dsb->SetVolume(DSBVOLUME_MIN);
		ps = 0;
		if (m_dsb)m_dsb->Stop();
		if (pAudioClient) pAudioClient->Stop();
		if (m_dou.GetCheck() == 1)
			if (cc1 == 1) {
				/* ユーザー停止: xfade チェックでも確定クローズ */
				PlaybackCcCloseIfNeeded(true);
			}
		MicMixCaptureStop();
		if (savedata.mic_mix)
			MicMixCaptureStart();
		CCriticalLock _ccl(&cs);
		stf = 1;
		_ccl.Leave();
		// 曲切替中は上限付き。無限 Join は DS Lock 固着で UI 永久停止の原因になる。
		// Join 中は DoEvent しない（再入 UAF 防止）
		const DWORD joinTimeout = g_interactiveTrackChange
			? (g_playbackNotifyJoinTimeoutMs ? g_playbackNotifyJoinTimeoutMs : 2500u)
			: 0u;
		if (!WaitForPlaybackNotifyThreadExit(joinTimeout)) {
			// タイムアウトでも停止フラグを残すと、続く play() の CWread/adbuf が
			// IsPlaybackStopRequested で無音になる。デコーダは触らずフラグだけ戻す。
			thn1 = FALSE;
			stf = 0;
			SongParams_OnSongStopped();
			return;
		}
		SongParams_OnSongStopped();

		Closeds();
		//		FreeOutputBuffer();
		plf = 0;

		if (ogg)ReleaseOggVorbis(&ogg);

		ogg = NULL;

		//		for(int l=0;l<20;l++){Sleep(50);DoEvent();}
		if (adbuf2)free(adbuf2);//delete [] adbuf2;
		adbuf2 = NULL;
		// mode ではなく「実際に Open 中の形式」（曲切替前に Get が mode を差し替えても正しい）
		const int stoppingMode = PeekOpenDecoderMode(mode);
		if (stoppingMode == -10) { mp3_.Close(); g_mp3_decoder_bps = 16; }
		if (stoppingMode == -8) flac_.Close(og->kmp);
		if (stoppingMode == -9) m4a_.Close(og->kmp);
		if (stoppingMode == -7) dsd_.kpiClose(og->kmp);
		if (stoppingMode == 999) wav_.Close();
		if (stoppingMode == MODE_VST_MIDI) CloseVstMidiSession();
		if (stoppingMode == MODE_PLUGIN_WINAMP) PluginWinamp_Close();
		if (stoppingMode == MODE_PLUGIN_XMPLAY) PluginXmplay_Close();
		if (stoppingMode == MODE_PLUGIN_AIMP) PluginAimp_Close();
		kmp = NULL;
		ClearOpenDecoderMode();
		ReleaseKpiPlaybackAsync(mod, kmp1, hDLLk);
		thn1 = FALSE;
		stf = 0;
		// Join/解放後に DoEvent しない（再入で別形式の play が走り UAF になる）
		thend = 1;
		fadeadd = 0; fade = 1.0;
	}
	if (pMainFrame1 != NULL)
		pMainFrame1->stop();
	else if ((mode == -2 || videoonly) && pMediaControl)
		pMediaControl->Stop();
	gamenkill();
	videoonly = FALSE;
	plf = 0;
	playf = 0;
	if (::IsWindow(m_PianoRollDlg->GetSafeHwnd()))
		m_PianoRollDlg->ResetPlaybackState();
	if (::IsWindow(m_AnalyzerDlg->GetSafeHwnd()))
		m_AnalyzerDlg->ResetPlaybackState();
	m_analyzerSyncValid = FALSE;
	if (wav) free(wav);
	wav = NULL;
	mode = modesub;
	stflg = FALSE;
	SetTimer(4923, 30, NULL);
	m_lrc.SetWindowText(L"");
	m_lrc2.SetWindowText(LL14(L"歌詞(.lrc)が表示されます", L"Lyrics (.lrc) will be displayed here", L"Paroles (.lrc) affichees ici", L"Testi (.lrc) visualizzati qui", L"Letra (.lrc) mostrada aqui", L"가사(.lrc)가 여기에 표시됩니다", L"歌词(.lrc)将在此显示", L"كلمات (.lrc) ستُعرض هنا", L"Текст (.lrc) отображается здесь", L"Liedtext (.lrc) wird hier angezeigt", L"Letra (.lrc) exibida aqui", L"Songtekst (.lrc) wordt hier getoond", L"Teksty (.lrc) wy?wietlone tutaj", L"Soz (.lrc) burada goruntulenir"));
	m_lrc3.SetWindowText(L"");
	m_lrc4.SetWindowText(L"");
	m_lrc5.SetWindowText(L"");

	ResetPauseButtonUi();
	eqflg = TRUE;
	if (pl && plw && pl->pnt >= 0 && pl->pnt < pl->playcnt)
		ApplyPlaylistRowDisplay(pl->pc[pl->pnt]);
	ResumePromptKillQueued();
	ResumeDrainQueuedKeyDowns();
	MpPromptOnPlaybackStop();
	/* notify 未稼働でも xfade チェック WAV を確定 */
	PlaybackCcCloseIfNeeded(true);
}

BOOL COggDlg::stop1()
{

	// 再入（Join 後の旧 DoEvent や play 中のメッセージ）ではデコーダを触らない
	if (s_inStop1) {
		SignalPlaybackNotifyThreadStop();
		// play() 側は戻り値を見ずに続行するため、再入でもフラグは下ろしておく
		thn1 = FALSE;
		stf = 0;
		thend1 = FALSE;
		return TRUE;
	}
	s_inStop1 = true;
	struct ClearInStop1 { ~ClearInStop1() { s_inStop1 = false; } } _clearInStop1;

	// 孤児 CWread の遅延 SetSelection を無効化
	InterlockedIncrement(&g_cwreadEpoch);

	// playlist Get() が mode を次曲形式に差し替えた後でも、Open 中の形式で閉じる
	const int stoppingMode = PeekOpenDecoderMode(mode);

	// DoEvent 再入より先に解析を止める（形式違いの曲切替クラッシュ防止）
	playf = 0;
	plf = 0;
	TempoPredReset(0.0, 0.0, 1.0);
	TempoPredStopClock();
	g_tpLastLoopcnt = -1;
	g_tpUiValid = 0;
	InterlockedExchange(&g_tpLoopPending, 0);
	// SongParams_OnSongStopped は Join 後に呼ぶ(再生スレッドが Sync 中に UI/ロックを掴むため)
	if (::IsWindow(m_PianoRollDlg->GetSafeHwnd()))
		m_PianoRollDlg->PauseAnalysis();
	if (::IsWindow(m_AnalyzerDlg->GetSafeHwnd()))
		m_AnalyzerDlg->PauseFeed();

	// 形式を問わず停止要求。Join 前にデコーダを閉じない。
	SignalPlaybackNotifyThreadStop();
	KillTimer(1250);
	KillTimer(9000);

	// CWread 中断要求。完了後は必ず thend1 を下ろす（残すと次の CWread が即死する）
	if (thend == FALSE) {
		thend1 = TRUE;
		for (int kk = 0; kk < 50; kk++) {
			if (thend == 1) break;
			SignalPlaybackNotifyThreadStop();
			Sleep(1);
		}
	}
	// CWread が thend1 を見て return してから AfxEndThread するまでの猶予。
	Sleep(50);
	playb = 0;
	thend = 1;
	thend1 = FALSE;

	fade1 = 0;
	endflg = 0;

	if (!img.IsNull()) {
		img.Destroy();
	}
	jx = -1;
	lrc_backup = L"";
	lrccur = 0;
	loop1_2 = -1;

	//	for(int i=0;i<10;i++){DoEvent();Sleep(10);}
	if (ptl)ptl->SetProgressValue(m_hWnd, (LONGLONG)0, (LONGLONG)1);
	if (ptl)ptl->SetProgressState(m_hWnd, TBPF_NOPROGRESS);

	if (m_dsb)m_dsb->SetVolume(DSBVOLUME_MIN);
	ps = 0;
	if (m_dsb)m_dsb->Stop();
	if (pAudioClient) pAudioClient->Stop();
	if (m_dou.GetCheck() == 1)
		if (cc1 == 1) {
			PlaybackCcCloseIfNeeded(false);
		}
	MicMixCaptureStop();
	if (savedata.mic_mix)
		MicMixCaptureStart();
	{
		CCriticalLock _ccl(&cs);
		stf = 1;
		_ccl.Leave();
	}
	// play() 先頭の stop1 は Join 成否に関わらず続行する。
	// FALSE で return すると CWread に入らず 0:00／古い loop のままになる。
	// ただし対話的な曲切替では無限 Join 禁止(DS Lock / 旧 SaveFile 固着で UI 永久停止)。
	BOOL joined = TRUE;
	{
		const DWORD joinTimeout = g_interactiveTrackChange
			? (g_playbackNotifyJoinTimeoutMs ? g_playbackNotifyJoinTimeoutMs : 2500u)
			: 0u;
		joined = WaitForPlaybackNotifyThreadExit(joinTimeout);
	}
	thn1 = FALSE;
	stf = 0;
	thend1 = FALSE;
	SongParams_OnSongStopped();

	// Join 失敗時はデコーダを触らない(生存スレッドの UAF 防止)。play() は続行するが
	// PeekOpenDecoderMode が残っていれば次の Open 前に再停止がかかる。
	if (!joined) {
		playf = 0;
		plf = 0;
		return FALSE;
	}

	Closeds();
	//		FreeOutputBuffer();
	plf = 0;
	if (ogg)ReleaseOggVorbis(&ogg);
	ogg = NULL;

	// デコーダ解放は必ず Join 後（flac/m4a/dsd/wav は通知スレッドが Render 中）
	if (adbuf2) {
		free(adbuf2);
		adbuf2 = NULL;
	}
	/* クロスフェード副スロットも閉じる */
	{
		/* 先読み中に閉じると壊れる。開き終わらない場合は開いた側が自分で破棄する */
		const int preloadIdle = XfPreloadCancel(4000);
		const int act = XfActiveSlot();
		const int oth = XfOtherSlot(act);
		if (preloadIdle && g_openDecoderModeSlot[oth] != INT_MIN)
			XfCloseSlotDecoders(oth);
		InterlockedExchange(&g_xfInProgress, 0);
		InterlockedExchange(&g_xfOpening, 0);
		InterlockedExchange(&g_xfPrepared, 0);
	}
	wav999_use_adbuf = 0;
	if (stoppingMode == -10) { mp3_.Close(); g_mp3_decoder_bps = 16; }
	if (stoppingMode == -8 && kmp) { flac_.Close(kmp); }
	if (stoppingMode == -9 && kmp) { m4a_.Close(kmp); }
	if (stoppingMode == -7 && kmp) { dsd_.kpiClose(kmp); }
	if (stoppingMode == 999) wav_.Close();
	if (stoppingMode == MODE_VST_MIDI) CloseVstMidiSession();
	if (stoppingMode == MODE_PLUGIN_WINAMP) PluginWinamp_Close();
	if (stoppingMode == MODE_PLUGIN_XMPLAY) PluginXmplay_Close();
	if (stoppingMode == MODE_PLUGIN_AIMP) PluginAimp_Close();
	kmp = NULL;
	ClearOpenDecoderMode();
	ReleaseKpiPlaybackAsync(mod, kmp1, hDLLk);

	fadeadd = 0; fade = 1.0;
	// 解放完了後に初めて停止フラグを下ろす（play() 先頭でも下ろすが、ここでも戻す）
	thn1 = FALSE;
	stf = 0;

	if (pMainFrame1 != NULL)
		pMainFrame1->stop();
	gamenkill();
	videoonly = FALSE;
	plf = 0;
	playf = 0;
	if (::IsWindow(m_PianoRollDlg->GetSafeHwnd()))
		m_PianoRollDlg->ResetPlaybackState();
	if (::IsWindow(m_AnalyzerDlg->GetSafeHwnd()))
		m_AnalyzerDlg->ResetPlaybackState();
	m_analyzerSyncValid = FALSE;
	if (wav) free(wav);
	wav = NULL;
	mode = modesub;
	m_lrc.SetWindowText(L"");
	m_lrc2.SetWindowText(LL14(L"歌詞(.lrc)が表示されます", L"Lyrics (.lrc) will be displayed here", L"Paroles (.lrc) affichees ici", L"Testi (.lrc) visualizzati qui", L"Letra (.lrc) mostrada aqui", L"가사(.lrc)가 여기에 표시됩니다", L"歌词(.lrc)将在此显示", L"كلمات (.lrc) ستُعرض هنا", L"Текст (.lrc) отображается здесь", L"Liedtext (.lrc) wird hier angezeigt", L"Letra (.lrc) exibida aqui", L"Songtekst (.lrc) wordt hier getoond", L"Teksty (.lrc) wy?wietlone tutaj", L"Soz (.lrc) burada goruntulenir"));
	m_lrc3.SetWindowText(L"");
	m_lrc4.SetWindowText(L"");
	m_lrc5.SetWindowText(L"");
	ResetPauseButtonUi();
	eqflg = TRUE;
	return TRUE;
}

