BOOL COggDlg::PreTranslateMessage(MSG* pMsg)
{
	// メディアプレイヤーモード: DoModal 中は mp の PreTranslateMessage が呼ばれない。
	// あいまい検索欄の Enter をここで中継し、og の IDOK(終了)へ流さない。
	if (savedata.playerMode == 1) {
		extern BOOL Soft3DMazePreTranslate(MSG*);
		if (Soft3DMazePreTranslate(pMsg))
			return TRUE;
		extern BOOL Soft3DRacePreTranslate(MSG*);
		if (Soft3DRacePreTranslate(pMsg))
			return TRUE;
		extern CMediaPlayerDlg* mp;
		if (mp && ::IsWindow(mp->GetSafeHwnd()) && mp->RelayPreTranslateMessage(pMsg))
			return TRUE;
	} else if (m_setteiii.GetSafeHwnd()
		&& (pMsg->message == WM_RBUTTONUP || pMsg->message == WM_CONTEXTMENU)
		&& pMsg->hwnd == m_setteiii.GetSafeHwnd()) {
		// ファルコムUIの設定ボタン: フルダイアログなしでクイック変更
		extern CMediaPlayerDlg* mp;
		CPoint sp;
		if (pMsg->message == WM_CONTEXTMENU) {
			sp.x = (short)LOWORD(pMsg->lParam);
			sp.y = (short)HIWORD(pMsg->lParam);
			if (sp.x == -1 && sp.y == -1)
				::GetCursorPos(&sp);
		} else {
			sp.x = (short)LOWORD(pMsg->lParam);
			sp.y = (short)HIWORD(pMsg->lParam);
			m_setteiii.ClientToScreen(&sp);
		}
		if (mp && ::IsWindow(mp->GetSafeHwnd()))
			mp->ShowSettingsExtrasMenu(sp);
		else
			MpShowSettingsExtrasMenu(this, sp);
		return TRUE;
	}
	if (m_tooltip.GetSafeHwnd())
		m_tooltip.RelayEvent(pMsg);
	return CCustomBlurDialogBase::PreTranslateMessage(pMsg);
}

