extern IMediaEvent* pMediaEvent;


static int g_ccFmtRate = 0;
static int g_ccFmtCh = 0;
static int g_ccFmtBits = 0;
static volatile LONG g_ccFmtLocked = 0;
static AudioUpscaler s_ccUpscaler;
static int s_ccCfgSrcRate = 0, s_ccCfgSrcCh = 0, s_ccCfgSrcBits = 0;
static int s_ccCfgDstRate = 0, s_ccCfgDstCh = 0, s_ccCfgDstBits = 0;

// --- WAV保存時マイクミックス (ライブ m_c2 のみ。オフライン ExportToWav には混ぜない) ---
enum { MIC_RING_FRAMES = 16384, MIC_RING_CH = 2, MIC_MIX_SCRATCH = 512 * 1024 };
static float g_micRing[MIC_RING_FRAMES * MIC_RING_CH];
static volatile LONG g_micW = 0;
static volatile LONG g_micR = 0;
static int g_micCapRate = 0;
static int g_micCapCh = 0;
static volatile LONG g_micRun = 0;
static volatile LONG g_micStop = 0;
static volatile LONG g_micPeak = 0; // 0..1000 UI用
static HANDLE g_micThread = NULL;
static CRITICAL_SECTION g_micCs;
static volatile LONG g_micCsInit = 0;
static BYTE g_micMixScratch[MIC_MIX_SCRATCH];
static VcVocalTract g_mpMicVc;

int MpMicPeakLevel()
{
	LONG v = InterlockedCompareExchange(&g_micPeak, 0, 0);
	InterlockedExchange(&g_micPeak, v * 88 / 100);
	if (v <= 0) return 0;
	if (v > 1000) v = 1000;
	int ui = (int)(sqrt((double)v / 1000.0) * 1000.0 * 1.15);
	if (ui < 1) ui = 1;
	if (ui > 1000) ui = 1000;
	return ui;
}

static void MicMixEnsureCs()
{
	if (InterlockedCompareExchange(&g_micCsInit, 1, 0) == 0)
		InitializeCriticalSection(&g_micCs);
}

static void MicMixRingWrite(const float* interleaved, int frames, int ch)
{
	if (!interleaved || frames <= 0) return;
	if (ch < 1) ch = 1;
	if (ch > MIC_RING_CH) ch = MIC_RING_CH;

	// ボイスチェンジャー設定が有効なら、ミックス前にマイクへ適用
	float vcBuf[4096 * 2];
	const float* src = interleaved;
	int srcCh = ch;
	VcVocalParams vp;
	if (frames <= 4096 && VcParamsFromSavedata(vp)) {
		for (int i = 0; i < frames; ++i) {
			const float L = interleaved[i * ch];
			const float R = (ch >= 2) ? interleaved[i * ch + 1] : L;
			vcBuf[i * 2 + 0] = L;
			vcBuf[i * 2 + 1] = R;
		}
		const int rate = (g_micCapRate > 8000) ? g_micCapRate : 48000;
		VcProcessInterleavedStereo(g_mpMicVc, vcBuf, frames, rate, vp);
		src = vcBuf;
		srcCh = 2;
	}

	EnterCriticalSection(&g_micCs);
	LONG w = g_micW;
	for (int i = 0; i < frames; ++i) {
		const int wi = (int)(w % MIC_RING_FRAMES);
		float L = src[i * srcCh];
		float R = (srcCh >= 2) ? src[i * srcCh + 1] : L;
		g_micRing[wi * MIC_RING_CH + 0] = L;
		g_micRing[wi * MIC_RING_CH + 1] = R;
		w++;
	}
	g_micW = w;
	// 読取が遅れすぎたら追いつかせる(約リング半分)
	LONG r = g_micR;
	if ((LONG)(w - r) > (MIC_RING_FRAMES - 64))
		g_micR = w - (MIC_RING_FRAMES / 2);
	LeaveCriticalSection(&g_micCs);
}

static UINT __stdcall MicMixCaptureThread(void*)
{
	HRESULT hrCo = CoInitializeEx(NULL, COINIT_MULTITHREADED);
	IMMDeviceEnumerator* enumer = NULL;
	IMMDevice* device = NULL;
	IAudioClient* client = NULL;
	IAudioCaptureClient* capture = NULL;
	WAVEFORMATEX* mixFmt = NULL;
	HANDLE hEvent = NULL;

	hrCo; // CoInitialize 失敗でも続行を試行(既初期化の場合あり)
	HRESULT hr = CoCreateInstance(__uuidof(MMDeviceEnumerator), NULL, CLSCTX_ALL,
		__uuidof(IMMDeviceEnumerator), (void**)&enumer);
	if (FAILED(hr) || !enumer) goto mic_done;

	if (savedata.mic_device[0]) {
		hr = enumer->GetDevice(savedata.mic_device, &device);
		if (FAILED(hr) || !device) {
			if (device) { device->Release(); device = NULL; }
			hr = enumer->GetDefaultAudioEndpoint(eCapture, eConsole, &device);
		}
	} else {
		hr = enumer->GetDefaultAudioEndpoint(eCapture, eConsole, &device);
	}
	if (FAILED(hr) || !device) goto mic_done;

	hr = device->Activate(__uuidof(IAudioClient), CLSCTX_ALL, NULL, (void**)&client);
	if (FAILED(hr) || !client) goto mic_done;

	hr = client->GetMixFormat(&mixFmt);
	if (FAILED(hr) || !mixFmt) goto mic_done;

	hEvent = CreateEvent(NULL, FALSE, FALSE, NULL);
	if (hEvent) {
		hr = client->Initialize(AUDCLNT_SHAREMODE_SHARED,
			AUDCLNT_STREAMFLAGS_EVENTCALLBACK | AUDCLNT_STREAMFLAGS_NOPERSIST,
			2000000, 0, mixFmt, NULL);
		if (SUCCEEDED(hr))
			hr = client->SetEventHandle(hEvent);
		if (FAILED(hr)) {
			// EVENTCALLBACK 失敗時はポーリングへ(IAudioClient は再 Activate が必要)
			CloseHandle(hEvent); hEvent = NULL;
			client->Release(); client = NULL;
			CoTaskMemFree(mixFmt); mixFmt = NULL;
			hr = device->Activate(__uuidof(IAudioClient), CLSCTX_ALL, NULL, (void**)&client);
			if (FAILED(hr) || !client) goto mic_done;
			hr = client->GetMixFormat(&mixFmt);
			if (FAILED(hr) || !mixFmt) goto mic_done;
			hr = client->Initialize(AUDCLNT_SHAREMODE_SHARED,
				AUDCLNT_STREAMFLAGS_NOPERSIST,
				2000000, 0, mixFmt, NULL);
		}
	} else {
		hr = client->Initialize(AUDCLNT_SHAREMODE_SHARED,
			AUDCLNT_STREAMFLAGS_NOPERSIST,
			2000000, 0, mixFmt, NULL);
	}
	if (FAILED(hr)) goto mic_done;
	hr = client->GetService(__uuidof(IAudioCaptureClient), (void**)&capture);
	if (FAILED(hr) || !capture) goto mic_done;

	g_micCapRate = (int)mixFmt->nSamplesPerSec;
	g_micCapCh = (int)mixFmt->nChannels;
	if (g_micCapRate < 8000) g_micCapRate = 48000;
	if (g_micCapCh < 1) g_micCapCh = 1;
	InterlockedExchange(&g_micW, 0);
	InterlockedExchange(&g_micR, 0);
	hr = client->Start();
	if (FAILED(hr)) goto mic_done;
	InterlockedExchange(&g_micRun, 1);

	while (InterlockedCompareExchange(&g_micStop, 0, 0) == 0) {
		if (hEvent) {
			DWORD wr = WaitForSingleObject(hEvent, 50);
			if (wr != WAIT_OBJECT_0 && wr != WAIT_TIMEOUT) break;
		} else {
			Sleep(10);
		}
		UINT32 packet = 0;
		hr = capture->GetNextPacketSize(&packet);
		while (SUCCEEDED(hr) && packet > 0 && InterlockedCompareExchange(&g_micStop, 0, 0) == 0) {
			BYTE* data = NULL;
			UINT32 frames = 0;
			DWORD flags = 0;
			hr = capture->GetBuffer(&data, &frames, &flags, NULL, NULL);
			if (FAILED(hr)) break;
			if (frames > 0 && data && !(flags & AUDCLNT_BUFFERFLAGS_SILENT)) {
				const WORD tag = mixFmt->wFormatTag;
				const WORD bits = mixFmt->wBitsPerSample;
				const int ch = (int)mixFmt->nChannels;
				float conv[4096 * 2];
				UINT32 done = 0;
				while (done < frames) {
					UINT32 n = frames - done;
					if (n > 4096) n = 4096;
					for (UINT32 i = 0; i < n; ++i) {
						float L = 0.f, R = 0.f;
						if (tag == WAVE_FORMAT_IEEE_FLOAT || (tag == WAVE_FORMAT_EXTENSIBLE && bits == 32
							&& ((WAVEFORMATEXTENSIBLE*)mixFmt)->SubFormat == s_KSDATAFORMAT_SUBTYPE_IEEE_FLOAT)) {
							const float* f = (const float*)(data + (done + i) * mixFmt->nBlockAlign);
							L = f[0];
							R = (ch >= 2) ? f[1] : L;
						} else if (bits == 16) {
							const short* s = (const short*)(data + (done + i) * mixFmt->nBlockAlign);
							L = (float)s[0] / 32768.f;
							R = (ch >= 2) ? ((float)s[1] / 32768.f) : L;
						} else if (bits == 24) {
							const BYTE* b = data + (done + i) * mixFmt->nBlockAlign;
							int v = (int)(b[0] | (b[1] << 8) | (b[2] << 16));
							if (v & 0x800000) v |= ~0xFFFFFF;
							L = (float)v / 8388608.f;
							if (ch >= 2) {
								int v2 = (int)(b[3] | (b[4] << 8) | (b[5] << 16));
								if (v2 & 0x800000) v2 |= ~0xFFFFFF;
								R = (float)v2 / 8388608.f;
							} else R = L;
						} else if (bits == 32) {
							const int* s = (const int*)(data + (done + i) * mixFmt->nBlockAlign);
							L = (float)s[0] / 2147483648.f;
							R = (ch >= 2) ? ((float)s[1] / 2147483648.f) : L;
						}
						conv[i * 2 + 0] = L;
						conv[i * 2 + 1] = R;
						const float aL = (L < 0.f) ? -L : L;
						const float aR = (R < 0.f) ? -R : R;
						const float pk = (aL > aR) ? aL : aR;
						const LONG pv = (LONG)(pk * 1000.f);
						const LONG cur = InterlockedCompareExchange(&g_micPeak, 0, 0);
						if (pv > cur) InterlockedExchange(&g_micPeak, pv > 1000 ? 1000 : pv);
					}
					MicMixRingWrite(conv, (int)n, 2);
					done += n;
				}
			}
			capture->ReleaseBuffer(frames);
			hr = capture->GetNextPacketSize(&packet);
		}
	}
	client->Stop();

mic_done:
	InterlockedExchange(&g_micRun, 0);
	if (capture) capture->Release();
	if (client) client->Release();
	if (mixFmt) CoTaskMemFree(mixFmt);
	if (device) device->Release();
	if (enumer) enumer->Release();
	if (hEvent) CloseHandle(hEvent);
	if (SUCCEEDED(hrCo) || hrCo == S_FALSE) CoUninitialize();
	return 0;
}

static void MicMixCaptureStop()
{
	InterlockedExchange(&g_micStop, 1);
	if (g_micThread) {
		WaitForSingleObject(g_micThread, 8000);
		CloseHandle(g_micThread);
		g_micThread = NULL;
	}
	InterlockedExchange(&g_micRun, 0);
	InterlockedExchange(&g_micStop, 0);
	g_micCapRate = 0;
	g_micCapCh = 0;
}

static void MicMixCaptureStart()
{
	MicMixEnsureCs();
	if (InterlockedCompareExchange(&g_micRun, 0, 0) != 0) return;
	// 初期化失敗でスレッドが既に終了していると handle だけ残り再開始できない → 回収
	if (g_micThread) {
		DWORD code = 0;
		if (GetExitCodeThread(g_micThread, &code) && code != STILL_ACTIVE) {
			CloseHandle(g_micThread);
			g_micThread = NULL;
		} else {
			return;
		}
	}
	InterlockedExchange(&g_micStop, 0);
	uintptr_t th = _beginthreadex(NULL, 0, MicMixCaptureThread, NULL, 0, NULL);
	g_micThread = (th) ? (HANDLE)th : NULL;
}

void MpMicMixRestartIfRunning()
{
	if (!savedata.mic_mix) return;
	MicMixCaptureStop();
	MicMixCaptureStart();
}

static void MicMixIntoPcm(BYTE* p, UINT n, int rate, int ch, int bits)
{
	if (!p || n == 0 || rate < 8000 || ch < 1) return;
	if (InterlockedCompareExchange(&g_micRun, 0, 0) == 0) return;
	if (g_micCapRate < 8000) return;
	const int bpf = (bits / 8) * ch;
	if (bpf <= 0 || (n % (UINT)bpf) != 0) return;
	const int frames = (int)(n / (UINT)bpf);
	if (frames <= 0) return;
	float gain = (float)savedata.mic_mix_level / 100.f;
	if (gain < 0.f) gain = 0.f;
	if (gain > 2.f) gain = 2.f;

	EnterCriticalSection(&g_micCs);
	LONG r = g_micR;
	const LONG w = g_micW;
	const double step = (double)g_micCapRate / (double)rate;
	double pos = 0.0;
	for (int fi = 0; fi < frames; ++fi) {
		LONG ri = r + (LONG)pos;
		float mL = 0.f, mR = 0.f;
		if (ri < w) {
			const int idx = (int)(ri % MIC_RING_FRAMES);
			mL = g_micRing[idx * MIC_RING_CH + 0] * gain;
			mR = g_micRing[idx * MIC_RING_CH + 1] * gain;
		}
		pos += step;
		BYTE* s = p + fi * bpf;
		if (bits == 16) {
			short* ps = (short*)s;
			int vL = (int)ps[0] + (int)(mL * 32767.f);
			int vR = (ch >= 2) ? ((int)ps[1] + (int)(mR * 32767.f)) : vL;
			if (vL > 32767) vL = 32767; if (vL < -32768) vL = -32768;
			if (vR > 32767) vR = 32767; if (vR < -32768) vR = -32768;
			ps[0] = (short)vL;
			if (ch >= 2) ps[1] = (short)vR;
			for (int c = 2; c < ch; ++c) {
				int v = (int)ps[c] + (int)(((c & 1) ? mR : mL) * 32767.f);
				if (v > 32767) v = 32767; if (v < -32768) v = -32768;
				ps[c] = (short)v;
			}
		} else if (bits == 24) {
			for (int c = 0; c < ch; ++c) {
				BYTE* b = s + c * 3;
				int v = (int)(b[0] | (b[1] << 8) | (b[2] << 16));
				if (v & 0x800000) v |= ~0xFFFFFF;
				float m = (c & 1) ? mR : mL;
				v += (int)(m * 8388607.f);
				if (v > 8388607) v = 8388607; if (v < -8388608) v = -8388608;
				b[0] = (BYTE)(v & 0xFF);
				b[1] = (BYTE)((v >> 8) & 0xFF);
				b[2] = (BYTE)((v >> 16) & 0xFF);
			}
		} else if (bits == 32) {
			int* ps = (int*)s;
			for (int c = 0; c < ch; ++c) {
				double v = (double)ps[c] + (double)((c & 1) ? mR : mL) * 2147483647.0;
				if (v > 2147483647.0) v = 2147483647.0;
				if (v < -2147483648.0) v = -2147483648.0;
				ps[c] = (int)v;
			}
		}
	}
	g_micR = r + (LONG)pos;
	LeaveCriticalSection(&g_micCs);
}

void PlaybackCcClearFormat()
{
	InterlockedExchange(&g_ccFmtLocked, 0);
	g_ccFmtRate = 0;
	g_ccFmtCh = 0;
	g_ccFmtBits = 0;
	s_ccUpscaler.Reset();
	s_ccCfgSrcRate = s_ccCfgSrcCh = s_ccCfgSrcBits = 0;
	s_ccCfgDstRate = s_ccCfgDstCh = s_ccCfgDstBits = 0;
}

bool PlaybackCcXfadeCheckMode()
{
	if (wavExportPath.GetLength() > 0 || g_isWavExportRendering)
		return false;
	if (!og || !::IsWindow(og->GetSafeHwnd()) || !og->m_c2.GetSafeHwnd())
		return false;
	if (og->m_c2.GetCheck() != 1)
		return false;
	return XfEnabled() != 0;
}

bool PlaybackCcShouldKeepOpen()
{
	if (cc1 != 1)
		return false;
	if (cc.m_hFile == CFile::hFileNull)
		return false;
	return PlaybackCcXfadeCheckMode();
}

void PlaybackCcCloseIfNeeded(bool force)
{
	if (cc1 != 1)
		return;
	if (!force && PlaybackCcShouldKeepOpen())
		return;
	if (cc.m_hFile != CFile::hFileNull) {
		FinalizeWavStreamHeaderRF64(cc);
		cc.Close();
	}
	cc1 = 0;
	PlaybackCcClearFormat();
}

UINT PlaybackCcWriteDsPcm(const void* p, UINT n, int rate, int ch, int bits)
{
	if (!PlaybackCcXfadeCheckMode() || cc1 != 1 || !p || n == 0)
		return 0;
	return PlaybackCcWriteFromFormat(p, n, rate, ch, bits, true);
}

void PlaybackCcLockFormat(int rate, int ch, int bits)
{
	if (InterlockedCompareExchange(&g_ccFmtLocked, 0, 0) != 0)
		return;
	if (rate < 8000) rate = 44100;
	if (ch < 1) ch = 2;
	if (!(bits == 16 || bits == 24 || bits == 32)) bits = 16;
	g_ccFmtRate = rate;
	g_ccFmtCh = ch;
	g_ccFmtBits = bits;
	InterlockedExchange(&g_ccFmtLocked, 1);
	// ロック形式が変わったら変換器も張り直す
	s_ccCfgSrcRate = s_ccCfgSrcCh = s_ccCfgSrcBits = 0;
	s_ccCfgDstRate = s_ccCfgDstCh = s_ccCfgDstBits = 0;
	s_ccUpscaler.Reset();
}

bool PlaybackCcFormatLocked()
{
	return InterlockedCompareExchange(&g_ccFmtLocked, 0, 0) != 0;
}

void PlaybackCcGetFormat(int& rate, int& ch, int& bits)
{
	rate = g_ccFmtRate;
	ch = g_ccFmtCh;
	bits = g_ccFmtBits;
}

UINT PlaybackCcWriteFromFormat(const void* p, UINT n, int srcRate, int srcCh, int srcBits, bool forced)
{
	if (g_mpPromptAnalyzeOnly && p && n > 0) {
		MpPromptAnalyzeFeed(p, n, srcRate, srcCh, srcBits);
		if (!PlaybackCcFormatLocked())
			PlaybackCcLockFormat(srcRate, srcCh, srcBits);
		return 0; // 解析専用: ファイルへは書かない
	}
	if (!p || n == 0) return 0;
	// WAVオフでも G:(wl) は進める。旧来は wl+=cnt と書込が分離だった
	if (cc1 != 1) return n;
	/* xfade チェック: デコード経路は書かない。DS ステージは forced=true で書く */
	if (!forced && PlaybackCcXfadeCheckMode())
		return n;
	const bool liveMic = (savedata.mic_mix != 0 && wavExportPath.GetLength() == 0 && !g_isWavExportRendering);
	if (liveMic && InterlockedCompareExchange(&g_micRun, 0, 0) == 0)
		MicMixCaptureStart();
	if (!PlaybackCcFormatLocked()) {
		PlaybackCcLockFormat(srcRate, srcCh, srcBits);
		if (liveMic) {
			UINT off = 0;
			while (off < n) {
				UINT chunk = n - off;
				if (chunk > MIC_MIX_SCRATCH) chunk = MIC_MIX_SCRATCH;
				memcpy(g_micMixScratch, (const BYTE*)p + off, chunk);
				MicMixIntoPcm(g_micMixScratch, chunk, srcRate, srcCh, srcBits);
				cc.Write(g_micMixScratch, chunk);
				off += chunk;
			}
		} else {
			cc.Write(p, n);
		}
		if (g_isWavExportRendering)
			MpDecodeProgressOnPcm(n, srcRate, srcCh, srcBits);
		return n;
	}
	if (srcRate == g_ccFmtRate && srcCh == g_ccFmtCh && srcBits == g_ccFmtBits) {
		if (liveMic) {
			UINT off = 0;
			while (off < n) {
				UINT chunk = n - off;
				if (chunk > MIC_MIX_SCRATCH) chunk = MIC_MIX_SCRATCH;
				memcpy(g_micMixScratch, (const BYTE*)p + off, chunk);
				MicMixIntoPcm(g_micMixScratch, chunk, srcRate, srcCh, srcBits);
				cc.Write(g_micMixScratch, chunk);
				off += chunk;
			}
		} else {
			cc.Write(p, n);
		}
		if (g_isWavExportRendering)
			MpDecodeProgressOnPcm(n, srcRate, srcCh, srcBits);
		return n;
	}
	// 毎書き込み Configure/Reset すると FIFO が消え、ダウンサンプルが壊れる
	if (srcRate != s_ccCfgSrcRate || srcCh != s_ccCfgSrcCh || srcBits != s_ccCfgSrcBits
		|| g_ccFmtRate != s_ccCfgDstRate || g_ccFmtCh != s_ccCfgDstCh || g_ccFmtBits != s_ccCfgDstBits) {
		s_ccUpscaler.Configure(srcRate, srcCh, srcBits, g_ccFmtRate, g_ccFmtCh, g_ccFmtBits);
		s_ccCfgSrcRate = srcRate;
		s_ccCfgSrcCh = srcCh;
		s_ccCfgSrcBits = srcBits;
		s_ccCfgDstRate = g_ccFmtRate;
		s_ccCfgDstCh = g_ccFmtCh;
		s_ccCfgDstBits = g_ccFmtBits;
	}
	s_ccUpscaler.PushInterleaved((const uint8_t*)p, (int)n);
	std::vector<uint8_t> out;
	// アップ時は増える。ダウン時は減るが余裕を持つ
	out.resize((size_t)n * 4 + 65536);
	int got = 0;
	int guard = 0;
	while (guard < 256) {
		++guard;
		if ((int)out.size() - got < 8192)
			out.resize(out.size() * 2);
		int pulled = s_ccUpscaler.PullInterleaved(out.data() + got, (int)out.size() - got);
		if (pulled <= 0) break;
		got += pulled;
	}
	if (got > 0) {
		if (liveMic) {
			UINT off = 0;
			while (off < (UINT)got) {
				UINT chunk = (UINT)got - off;
				if (chunk > MIC_MIX_SCRATCH) chunk = MIC_MIX_SCRATCH;
				MicMixIntoPcm(out.data() + off, chunk, g_ccFmtRate, g_ccFmtCh, g_ccFmtBits);
				off += chunk;
			}
		}
		cc.Write(out.data(), (UINT)got);
		if (g_isWavExportRendering)
			MpDecodeProgressOnPcm((UINT)got, g_ccFmtRate, g_ccFmtCh, g_ccFmtBits);
	}
	return (UINT)got;
}

// playwav* が渡すのは常にソースPCM。出力(g_ds_*)形式を名乗ると
// ヘッダだけ変換レート・中身は生ソースになり、192k→48k で再生が約4倍遅くなる。
static void PlaybackCcSourceFormat(int& rate, int& ch, int& bits)
{
	rate = (wavbit_sample_Hz >= 8000) ? wavbit_sample_Hz : 44100;
	ch = (wavchannel >= 1) ? wavchannel : 2;
	bits = abs(wavsam_depth);
	if (wavsam_depth < 0)
		bits = 16; // float 系は Render 後 int16
	if (!(bits == 8 || bits == 16 || bits == 24 || bits == 32))
		bits = 16;
}

UINT PlaybackCcWrite(const void* p, UINT n)
{
	int rate, ch, bits;
	PlaybackCcSourceFormat(rate, ch, bits);
	return PlaybackCcWriteFromFormat(p, n, rate, ch, bits, false);
}

UINT PlaybackCcWriteForced(const void* p, UINT n)
{
	int rate, ch, bits;
	PlaybackCcSourceFormat(rate, ch, bits);
	return PlaybackCcWriteFromFormat(p, n, rate, ch, bits, true);
}

void Ogg_FeedPianoRoll(const void* p, int n)
{
	if (og) og->FeedPianoRoll(p, n);
}


void COggDlg::OnRestart()
{
	if (OggIsResumePromptActive())
		return;
	const bool softBusy = false;
	if (InterlockedCompareExchange(&s_onRestartBusy, 1, 0) != 0)
		return;
	// play() 中の DoEvent 再入で stop() がフラグだけ立てると CWread/再生が壊れる。延期する。
	if (s_inPlay || s_inStop1) {
		InterlockedExchange(&s_onRestartBusy, 0);
		if (!softBusy)
			RequestPlaybackRestart(GetSafeHwnd());
		return;
	}
	struct RestartBusyGuard {
		COggDlg* dlg;
		~RestartBusyGuard() {
			InterlockedExchange(&s_onRestartBusy, 0);
			// soft play 直後に残った wanted は捨て済み想定。念のため soft 中は再投入しない。
			if (InterlockedExchange(&s_restartWanted, 0) != 0 && dlg && ::IsWindow(dlg->GetSafeHwnd()))
				RequestPlaybackRestart(dlg->GetSafeHwnd());
		}
	} restartBusyGuard{ this };
	struct InteractiveTrackGuard {
		InteractiveTrackGuard() { InterlockedExchange(&g_interactiveTrackChange, 1); }
		~InteractiveTrackGuard() { InterlockedExchange(&g_interactiveTrackChange, 0); }
	} interactiveTrackGuard;

	// TODO: この位置にコントロール通知ハンドラ用のコードを追加してください
	CString ti;
	// 二重DS昇格中は stop() しない（B を止める経路を減らし、play()/stop1 だけにする）
	if (true)
		stop();
	else if (m_dsb) {
		LONG v = (savedata.dsvol - 1) * 10;
		if (savedata.dsvol == -498) v = (savedata.dsvol - 1) * 7;
		if (v > 0) v = 0;
		if (v < DSBVOLUME_MIN) v = DSBVOLUME_MIN;
		m_dsb->SetVolume(v);
		m_dsb->Play(0, 0, DSBPLAY_LOOPING);
	}
	if (filen == _T("") && pl && pl->playcnt > 0)
		pl->RestoreSavedPlaybackRow();
	if (filen != "") {
		ti = filen.Right(filen.GetLength() - filen.ReverseFind('\\') - 1);
		int sub_ = mode;
		// ゲーム形式トラックは拡張子による上書きを行わない。
		// 各ゲームのBGMは ED6001.ogg / YS6xxx.ogg / *.wav 等、拡張子が
		// .ogg/.wav でもゲーム専用のデコード経路(BGMフォルダへのchdir等)が必須で、
		// 単体ファイル(modesub=-1等)として再生すると鳴らせない。
		// stop() により mode は再生対象アイテム本来のモード(=pc[i].sub)へ復元済みなので、
		// それを用いてゲーム形式か否かを判定する。
		const bool isGameMode =
			(mode >= 1 && mode <= 30) ||
			mode == -11 || mode == -12 || mode == -13 || mode == -14 || mode == -15;
		// ネイティブ音声形式は拡張子のみで判定（game形式等からの切り替えも可能に）
		if (!isGameMode && filen.Right(5).MakeLower() == ".opus") {
			modesub = -6;
			playb = 0;
			play();
		}
		else if (!isGameMode && (filen.Right(4).MakeLower() == ".ogg" || filen.Right(4) == ".OGG" || filen.Right(6).MakeLower() == ".qull3")) {
			modesub = -1;
			play();
		}
		else if (!isGameMode && (filen.Right(4).MakeLower() == ".dsf" || filen.Right(5) == ".DSF" || filen.Right(4).MakeLower() == ".dff" || filen.Right(4) == ".DFF" || filen.Right(4).MakeLower() == ".wsd" || filen.Right(4) == ".WSD")) {
			modesub = -7;
			play();
		}
		else if (!isGameMode && (filen.Right(5).MakeLower() == ".flac" || filen.Right(5) == ".FLAC" || filen.Right(7).MakeLower() == L".qull3h")) {
			modesub = -8;
			play();
		}
		else if (!isGameMode && (filen.Right(4).MakeLower() == ".m4a" || filen.Right(4) == ".M4A" || filen.Right(4).MakeLower() == ".aac" || filen.Right(4) == ".AAC")) {
			modesub = -9;
			play();
		}
		else if (!isGameMode && (filen.Right(4).MakeLower() == ".mp3" || filen.Right(4) == ".MP3" || filen.Right(4).MakeLower() == ".mp2" || filen.Right(4) == ".MP2" ||
			filen.Right(4).MakeLower() == ".mp1" || filen.Right(4) == ".MP1" || filen.Right(4).MakeLower() == ".rmp" || filen.Right(4) == ".RMP")) {
			modesub = -10;
			play();
		}
		else if (!isGameMode && (filen.Right(4).MakeLower() == ".wav" || filen.Right(4) == ".WAV")) {
			modesub = 999;
			play();
		}
		else if (isGameMode) {
			if (mode == 19) filen = filen.Left(5);
			modesub = mode;
			play();
		}
		else if (mode == -2 || mode == -3 || IsForeignPluginMode(mode)) {
			playlistdata p;
			kpi[0] = 0;
			if (pl && plw) {
				p.sub = 0;
				CString ss, s;
				s = filen;
				{
					uint32_t sel = 1;
					SplitKpiSubsongPath(s, ss, sel);
				}
				if (ss != "") s = ss;
				pl->plugs(s, &p, kpi, kvver);
				if (p.sub == -3) {//kb medua player
					s = kpi;
					ss = s.Left(s.ReverseFind('\\'));
					_tchdir(ss);
					//					hDLLk = LoadLibrary(kpi);
					//					pFunck = (pfnGetKMPModule)::GetProcAddress(hDLLk, "kmp_GetTestModule");
					mode = -3;
					modesub = -3;
					play();
					return;
				}
				// Winamp/XMPlay/AIMP も KPI 同様に毎回 kpi[] を引き直す。
				// ここを通さないと前の曲のプラグインパスのまま Open して必ず失敗し、
				// プレイリスト経由の再生だけが「開けません」→ DirectShow(-2) に落ちる。
				if (IsForeignPluginMode(p.sub)) {
					s = kpi;
					const int slash = s.ReverseFind('\\');
					if (slash > 0) {
						ss = s.Left(slash);
						_tchdir(ss);
					}
					mode = modesub = p.sub;
					play();
					return;
				}
			}
			fnn = ti;
			stflg = FALSE;
			modesub = -2; mode = -2;
			// グラフ構築(play)の前に確認 → ダイアログ表示までの待ちを短縮
			const int flggg = PromptResumePlaybackIfSaveExists(this, filen);
			if (pMainFrame1)
				gamenkill();
			pMainFrame1 = new CDouga;
			pMainFrame1->Create(GetSafeHwnd());
			pMainFrame1->ShowWindow(SW_HIDE);
			pMainFrame1->play(0);
			CFile f123;
			if (flggg == 1 && f123.Open(ResumeSavePathRead(filen), CFile::modeRead | CFile::shareDenyWrite, NULL) == TRUE) {
				f123.Close();
				if (pMainFrame1 && pGraphBuilder)pMainFrame1->plays2();
				double resumeAa = 0.0;
				if (ResumeDshowApplies(mode, filen)) {
					if (f123.Open(ResumeSavePathRead(filen), CFile::modeRead | CFile::shareDenyWrite, NULL) == TRUE) {
						f123.Read(&resumeAa, sizeof(double));
						f123.Close();
						aa1_ = resumeAa;
					}
				}
				DougaRunThenSeek(resumeAa);
			}
			else {
				if (pMainFrame1 && pGraphBuilder)pMainFrame1->plays2();
				TryRunMediaControlQuick();
			}
			int a = 0; aa2 = 0;
			REFTIME aa = 0;
			aa2 = 0;
			ResetPauseButtonUi();
			if (pMediaPosition)pMediaPosition->get_StopTime(&aa);
			aa1 = oggsize2 = aa;
			m_time.SetRange(0, (int)((REFTIME)aa * 100.0), TRUE);
			m_time.SetSelection(0, (int)((REFTIME)aa * 100.0) - 1);
			m_time.Invalidate();
			if (pl && plw && !pl->m_tempMode) {
				int plc = -1;
				plc = pl->Add(fnn, mode, 0, 0, _T(""), _T(""), filen, 0, (int)aa, 1);
				if (plc == -1) {
					int i = pl->m_lc.GetItemCount() - 1;
					plcnt = i;
					pl->SIcon(i);
				}
				else {
					plcnt = plc;
					pl->SIcon(plc);
				}
			}
			SetTimer(1250, 100, NULL);
			plf = 1;
		}
		else {
			if (mode == 19)filen = filen.Left(5);
			play();
		}

	}
}


template<int Radius>
static inline float Lanczos(float x)
{
	if (x == 0.0) return 1.0;
	if (x <= -Radius || x >= Radius) return 0.0;
	float pi_x = x * M_PI;
	return Radius * sin(pi_x) * sin(pi_x / Radius) / (pi_x * pi_x);
}

const int FilterRadius = 3;

static inline void ResampleDouble(const double* source, size_t src_len, double* result, size_t dest_len) {
	if (src_len == dest_len) {
		memcpy(result, source, src_len * sizeof(double));
		return;
	}

	double scale = (double)src_len / (double)dest_len;
	for (size_t i = 0; i < dest_len; i++) {
		double src_pos = i * scale;
		size_t src_idx = (size_t)src_pos;
		double frac = src_pos - src_idx;

		if (src_idx >= src_len - 1) {
			result[i] = source[src_len - 1];
		}
		else {
			result[i] = source[src_idx] * (1.0 - frac) + source[src_idx + 1] * frac;
		}
	}
}

