void COggDlg::OnHScroll(UINT nSBCode, UINT nPos, CScrollBar* pScrollBar)
{
	if (pScrollBar && m_miclev.GetSafeHwnd() && pScrollBar->GetSafeHwnd() == m_miclev.GetSafeHwnd()) {
		int lv = m_miclev.GetPos();
		if (lv < 0) lv = 0;
		if (lv > 200) lv = 200;
		savedata.mic_mix_level = lv;
		ApplyMicMixLevelLabel();
		if (nSBCode == SB_ENDSCROLL || nSBCode == SB_THUMBPOSITION)
			MpPersistSavedataQuick();
		return;
	}
	// HWND で判定（一時 CWnd* でも IDC が取れる）。カスタム GetPos は m_time を直接使う
	if (!pScrollBar || pScrollBar->GetSafeHwnd() != m_time.GetSafeHwnd()) return;

	int minpos;
	int maxpos;
	int curpos;
	double aa = 2000.0; // デフォルト値

	// サンプリングレートによる係数設定
	if (wavsam_depth == 32 || wavsam_depth == 24 || wavsam_depth == 16 || wavsam_depth == 8) aa = 2000.0;

	// トラック中のフラグ処理
	if (nSBCode == SB_THUMBTRACK) {
		hsc = 1;
		sflg = FALSE;
		return;
	}

	// 実際のシーク処理（移動を伴うもの）
	// SB_THUMBPOSITION: つまみを離した直後（環境によっては SB_ENDSCROLL が来ない）
	if (nSBCode == SB_PAGELEFT || nSBCode == SB_PAGERIGHT || nSBCode == SB_ENDSCROLL || nSBCode == SB_THUMBPOSITION) {

		// ★排他制御開始：再生スレッドとの競合を防ぐ
		std::unique_lock<std::mutex> hscroll_lock(cl2);

		// 二重スロット中はグローバルデコーダ/アップスケーラを触らない（閉じ済み kmp でクラッシュする）
		int dualSlot = -1;
		bool slotSeek = false;
		if (InterlockedCompareExchange(&g_xfInProgress, 0, 0)) {
			dualSlot = XfActiveSlot();
			slotSeek = true;
		}

		if (!slotSeek) {
			ResetAudioUpscalerPipeline();
			RubberBand_DestroyBank(XfActiveSlot());
		}
		else if (dualSlot >= 0 && dualSlot < XF_SLOTS) {
			g_audioUpscalerArr[dualSlot].Reset();
			RubberBand_DestroyBank(dualSlot);
		}

		m_time.GetRange(minpos, maxpos);
		curpos = m_time.GetPos();

		// ページ移動の計算
		if (nSBCode == SB_PAGELEFT) {
			int info = m_time.GetLineSize();
			if (curpos > minpos) curpos = max(minpos, curpos - info);
		}
		else if (nSBCode == SB_PAGERIGHT) {
			int info = m_time.GetLineSize();
			if (curpos < maxpos) curpos = min(maxpos, curpos + info);
			else { hsc = 2; sflg = FALSE; return; }
		}
		// SB_ENDSCROLL / SB_THUMBPOSITION の場合はこの時点の GetPos() が最終位置

		// テンポで壁時計レンジにしているので、デコード位置へ戻す
		const BOOL tempoSeek = !(pMediaPosition && (mode == -2 || (mode > 0 && videoonly == TRUE)));
		const double seekRate = tempoSeek ? TempoPlaybackRateFromPos(m_tempo_sl.GetPos()) : 1.0;
		int srcCur = tempoSeek ? WallToSrcSlider(curpos, seekRate) : curpos;

		// 位置の補正（mode==-2 では timerp が loop1=loop2=0 にするため、音声用クランプを掛けると常に先頭へ落ちる）
		// 二重スロット中も loop2==0（MP3）だと loop1+loop2 クランプで常に 0 になるので maxpos を使う
		if (pMediaPosition && (mode == -2 || (mode > 0 && videoonly == TRUE))) {
			if (curpos < minpos) curpos = minpos;
			if (curpos > maxpos) curpos = maxpos;
			srcCur = curpos;
		}
		else if (slotSeek) {
			if (curpos < minpos) curpos = minpos;
			if (curpos > maxpos) curpos = maxpos;
			srcCur = WallToSrcSlider(curpos, seekRate);
		}
		else {
			const int loopEnd = (loop2 > 0) ? (loop1 + loop2) : ((loop3 > 0) ? (loop1 + loop3) : 0);
			if (loopEnd > 0 && loopEnd < srcCur && endf == 0) srcCur = loopEnd;
			curpos = SrcToWallSlider(srcCur, seekRate);
			if (curpos > maxpos) curpos = maxpos;
			if (curpos < minpos) curpos = minpos;
		}

		// 二重スロット運用中は active スロットのデコーダへシーク（グローバル mp3_/flac_ は閉じ済み）
			m_time.SetPos(curpos);
		playb = (__int64)srcCur;
		// timerp の TempoPredRealSrcSamples が旧 poss5 を返すとシーク棒が即座に戻る
		poss5 = (int)srcCur;
		/* シーク中に xfade が走ると A がまごつくので一旦止める */
		XfPreloadCancel(0);
		if (InterlockedCompareExchange(&g_xfInProgress, 0, 0)
			|| InterlockedCompareExchange(&g_xfPrepared, 0, 0))
			XfAbortCrossfade();
		InterlockedExchange(&g_xfWantStart, 0);
		InterlockedExchange(&g_xfOpening, 0);
		g_endWrittenBytes = 0;
		endflg = 0;
		fade1 = 0;
		/* DS 再充填に要する短時間だけ xfade 開始を抑止（長すぎると「もたつき」に聞こえる） */
		g_seekUiHoldUntil = GetTickCount64() + 450;
		if (tempoSeek && wavbit_sample_Hz > 0) {
			const double srcSec = (mode == -10)
				? ((double)srcCur * 100.0 / (double)wavbit_sample_Hz)
				: ((double)srcCur / (double)wavbit_sample_Hz);
			const double wallSec = (seekRate > 0.05) ? (srcSec / seekRate) : srcSec;
			TempoPredReset(srcSec, wallSec, seekRate);
		}

		// 1. 動画・メディアポジションのシーク
		if (pMediaPosition && (mode == -2 || (mode > 0 && videoonly == TRUE))) {
			if (aa2 == 0) pMainFrame1->seek((LONGLONG)((float)curpos * 100000.0f));
			else         pMainFrame1->seek((LONGLONG)((float)curpos * 100000.0f));
			hsc = 0;
			poss = 0;
		}
		else {
			// 2. 音声エンジンのシーク
			if (pMainFrame1) {
				pMainFrame1->seek((LONGLONG)(((float)srcCur * 10000000.0f) / (float)wavbit_sample_Hz));
			}
			// 共通のバッファ・フラグ更新
			ZeroMemory(bufkpi, OUTPUT_BUFFER_SIZE * OUTPUT_BUFFER_NUM * 3);
			ZeroMemory(bufkpi_, OUTPUT_BUFFER_SIZE * OUTPUT_BUFFER_NUM * 3);
			ZeroMemory(bufkpi2, OUTPUT_BUFFER_SIZE * OUTPUT_BUFFER_NUM * 3);
			ZeroMemory(bufkpi3, OUTPUT_BUFFER_SIZE * OUTPUT_BUFFER_NUM * 3);
			ZeroMemory(bufkpi4, OUTPUT_BUFFER_SIZE * OUTPUT_BUFFER_NUM * 3);
			poss = 0;

			// adbuf2 全量読み込み形式(mode 10-21, -6, 30, -11〜 等)は seekadpcm
			if (((mode >= 10 && mode <= 21) || IsBuffwavNegMode(mode) || mode == 999 || mode == -6 || mode == 34 || mode == 35 || mode == 30)) {
				if (mode == -10) {
					hsc = 2;
					// m_time は壁時計。ソースフレーム = srcCur×100
					playb = (__int64)srcCur * 100;
					if (playb < 0) playb = 0;
					// timerp の TempoPredRealSrcSamples(=poss5) と揃えないとシーク直後に棒が跳ねる
					poss5 = (int)playb;

					/* Pause↔Resume は聞こえるもたつきになるので、再生中も FLAC 同様に直シーク */
					poss = 0; poss2 = 0; poss3 = 0; poss4 = 0; poss6 = 0;
					ZeroMemory(bufkpi, OUTPUT_BUFFER_SIZE * OUTPUT_BUFFER_NUM * 3);
					if (savedata.mp3orig) mp3_.seek2(Mp3SeekDwPosFromPlaybFrames(playb), wavchannel);
					else                  mp3_.seek(Mp3SeekDwPosFromPlaybFrames(playb), wavchannel);
					sek = TRUE; cnt3 = 0;
					timer.SetEvent();
				}
				else if (mode == 999) {
					hsc = 2;
					poss = 0; ZeroMemory(bufkpi, OUTPUT_BUFFER_SIZE * OUTPUT_BUFFER_NUM * 3);
					wav_.Seek(playb);
					sek = TRUE; cnt3 = 0;
					timer.SetEvent();
				}
				else {
					poss = 0; poss2 = 0; poss3 = 0; poss4 = 0; poss6 = 0;
					ZeroMemory(bufkpi, OUTPUT_BUFFER_SIZE * OUTPUT_BUFFER_NUM * 3);
					seekadpcm((int)playb);
				}
			}
			else if (mode == -3) { // KPI
				KpiSeekToPlayb(playb);
			}
			else if (mode == MODE_VST_MIDI) {
				VstSeekToPlayb(playb);
			}
			else if (mode == -7) { // DSD
				dsd_.kpiSetPosition(kmp, (DWORD)((double)playb / (((double)wavbit_sample_Hz * (double)wavchannel) / 2000.0)));
			}
			else if (mode == -8) { // FLAC
				if (kmp) {
					sek4 = TRUE;
					if (flacmode == 1) flac_.SetPosition(kmp, playb);
					else               flac_.SetPosition(kmp, (LONGLONG)((double)playb / (((double)wavbit_sample_Hz * (double)wavchannel) / aa)));
					::rrr = 1;  // シーク後は Render を再開
					sek4 = FALSE;
				}
			}
			else if (mode == -9) { // M4A
				if (kmp) {
					double wavv2[] = { 0, 2.0, 1.0, 1.0 / 2.0, 1.0 / 2.0, 1.0 / 2.0, 1.0 / 2.0 };
					DWORD pla = (DWORD)((double)playb / (((double)(wavbit2 / wavv2[wavchannel])) / ((wavchannel > 2) ? (1069.1 * wavchannel) : 1000.0)));
					pla = (pla / (wavchannel * 2) * (wavchannel * 2));
					m4a_.SetPosition(kmp, pla);
				}
			}
			else { // OGG / Others
				SeekAndWarmupRubberBand((int)srcCur, false);
				m_time.SetPos(curpos);
			}

			/* mode 別 playb/poss5 確定後に DS 累積を曲位置へ合わせる */
			{
				extern __int64 g_dsWrittenBytes, g_heardBytes;
				extern int g_outBytesPerFrame;
				__int64 aligned = XfPlayPosBytes();
				const int bpf = (g_outBytesPerFrame > 0) ? g_outBytesPerFrame : 4;
				if (bpf > 1 && aligned > 0)
					aligned -= (aligned % (__int64)bpf);
				g_dsWrittenBytes = (aligned > 0) ? aligned : 0;
				g_heardBytes = g_dsWrittenBytes;

				/* 書込みヘッド直後の短い区間だけ無音（リング全体を消すと無音ギャップ＝もたつき） */
				if (m_dsb) {
					DWORD pc = 0, wc = 0;
					if (m_dsb->GetCurrentPosition(&pc, &wc) == DS_OK) {
						const ULONG ring = (g_ds_buffer_bytes > 0) ? g_ds_buffer_bytes
							: (ULONG)(OUTPUT_BUFFER_SIZE * OUTPUT_BUFFER_NUM);
						extern int g_outBytesPerFrame;
						const int bpf = (g_outBytesPerFrame > 0) ? g_outBytesPerFrame : 4;
						const int rate = (g_ds_pcm_rate > 0) ? g_ds_pcm_rate : ((wavbit_sample_Hz > 0) ? wavbit_sample_Hz : 44100);
						ULONG zap = (ULONG)(bpf * rate / 100); /* ~10ms */
						if (zap < (ULONG)bpf * 4) zap = (ULONG)bpf * 4;
						if (zap > ring / 4) zap = ring / 4;
						LPVOID p1 = NULL, p2 = NULL;
						DWORD l1 = 0, l2 = 0;
						if (m_dsb->Lock(wc, zap, &p1, &l1, &p2, &l2, 0) == DS_OK) {
							if (p1 && l1) ZeroMemory(p1, l1);
							if (p2 && l2) ZeroMemory(p2, l2);
							m_dsb->Unlock(p1, l1, p2, l2);
						}
						oldw = wc;
					}
				}
			}

			sek = TRUE;
			cnt3 = 0;
			timer.SetEvent();
			hsc = 0;
		}
		// ★ここで hscroll_lock がスコープを抜け、自動的に解除される
	}
	sflg = FALSE;
}

